window.POEM_DB=window.POEM_DB||{};POEM_DB["gongzizhen"]={"n":"龚自珍","dyn":"清","poems":[{"t":"己亥杂诗 其五","f":"七言绝句","c":["浩荡离愁白日斜，吟鞭东指即天涯。","落红不是无情物，化作春泥更护花。"]},{"t":"己亥杂诗 其九十六","f":"七言绝句","c":["少年击剑更吹箫，剑气箫心一例消。","谁分苍凉归棹后，万千哀乐聚今朝。"]},{"t":"己亥杂诗 其一七○","f":"七言绝句","c":["少年哀乐过于人，歌泣无端字字真。","既壮周旋杂痴黠，童心来复梦中身。"]},{"t":"己亥杂诗 其一九五","f":"七言绝句","c":["天将何福予蛾眉，生死湖山全盛时。","冰雪无痕灵气杳，女仙不赋降坛诗。"]},{"t":"己亥杂诗 其一","f":"七言绝句","c":["著书何似观心贤，不奈卮言夜涌泉。","百卷书成南渡后，先生续集再编年。"]},{"t":"己亥杂诗 其二","f":"七言绝句","c":["我马玄黄盼日曛，关河不窘故将军。","百年心事归平淡，删尽蛾眉惜誓文。"]},{"t":"己亥杂诗 其三","f":"七言绝句","c":["罡风力大簸春魂，虎豹沈沈卧九阍。","终是落花心绪好，平生默感玉皇恩。"]},{"t":"己亥杂诗 其四","f":"七言绝句","c":["此去东山又北山，镜中强半尚红颜。","白云出处从无例，独往人间竟独还。"]},{"t":"己亥杂诗 其六","f":"七言绝句","c":["亦曾橐笔侍銮坡，午夜天风伴玉珂。","欲浣春衣仍护惜，乾清门外露痕多。"]},{"t":"己亥杂诗 其七","f":"七言绝句","c":["廉锷非关上帝才，百年淬厉电光开。","先生宦后雄谈减，悄向龙泉祝一回。"]},{"t":"己亥杂诗 其八","f":"七言绝句","c":["太行一脉走蝹蜿，莽莽畿西虎气蹲。","送我摇鞭竟东去，此山不语看中原。"]},{"t":"己亥杂诗 其十","f":"七言绝句","c":["进退雍容史上难，忽收古泪出长安。","百年綦辙低徊遍，忍作空桑三宿看。"]},{"t":"己亥杂诗 其十一","f":"七言绝句","c":["祖父头衔旧颎光，祠曹我亦试为郎。","君恩够向渔樵说，篆墓何须百字长。"]},{"t":"己亥杂诗 其十二","f":"七言绝句","c":["掌故罗胸是国恩，小胥脱腕万言存。","他年金匮如收采，来叩空山夜雨门。"]},{"t":"己亥杂诗 其十三","f":"七言绝句","c":["出事公卿溯戊寅，云烟万态马蹄湮。","当年筮仕还嫌晚，已哭同朝三百人。"]},{"t":"己亥杂诗 其十四","f":"七言绝句","c":["颓波难挽挽颓心，壮岁曾为九牧箴。","钟簴苍凉行色晚，狂言重起廿年瘖。"]},{"t":"己亥杂诗 其十五","f":"七言绝句","c":["许身何必定夔皋，简要清通已足豪。","读到嬴刘伤骨事，误渠毕竟是锥刀。"]},{"t":"己亥杂诗 其十七","f":"七言绝句","c":["金门缥缈廿年身，悔向云中露一鳞。","终古汉家狂执戟，谁疑臣朔是星辰？"]},{"t":"己亥杂诗 其十八","f":"七言绝句","c":["词家从不觅知音，累汝千回带泪吟。","惹得尔翁怀抱恶，小桥独立惨归心。"]},{"t":"己亥杂诗 其十九","f":"七言绝句","c":["卿筹烂熟我筹之，我有忠言质幻师。","观理自难观势易，弹丸垒到十枚时。"]},{"t":"己亥杂诗 其二十","f":"七言绝句","c":["消息闲凭曲艺看，考工文字太丛残。","五都黍尺无人校，抢攘廛间一饱难。"]},{"t":"己亥杂诗 其二十一","f":"七言绝句","c":["满拟新桑遍冀州，重来不见绿云稠。","书生挟策成何济？","付与维南织女愁。"]},{"t":"己亥杂诗 其二十四","f":"七言绝句","c":["谁肯栽培木一章，黄泥亭子白茅堂。","新蒲新柳三年大，便与儿孙作屋梁。"]},{"t":"己亥杂诗 其二十五","f":"七言绝句","c":["椎埋三辅饱于鹰，薛下人家六万增。","半与城门充校尉，谁将斜谷械阳陵？"]},{"t":"己亥杂诗 其二十六","f":"七言绝句","c":["逝矣斑骓罥落花，前村茅店即吾家。","小桥报有人痴立，泪泼春帘一饼茶。"]},{"t":"己亥杂诗 其二十七","f":"七言绝句","c":["秀出天南笔一支，为官风骨称其诗。","野棠花落城隅晚，各记春骢恋絷时。"]},{"t":"己亥杂诗 其三十","f":"七言绝句","c":["事事相同古所难，如鹣如鲽在长安。","从今两戒河山外，各逮而孙盟不寒。"]},{"t":"己亥杂诗 其三十一","f":"七言绝句","c":["本朝闽学自有派，文字醰醰多古情。","新识晋江陈户部，谈经颇似李文贞。"]},{"t":"己亥杂诗 其三十二","f":"七言绝句","c":["何郎才调本孪生，不据文家为弟兄。","嗜好毕同星命异，大郎尤贵二郎清。"]},{"t":"己亥杂诗 其三十三","f":"七言绝句","c":["少慕颜曾管乐非，胸中海岳梦中飞。","近来不信长安隘，城曲深藏此布衣。"]},{"t":"己亥杂诗 其三十四","f":"七言绝句","c":["猛龙当年入海初，婆娑曾否有仓祛？","祇今旷劫重生后，尚识人间七体书。"]},{"t":"己亥杂诗 其三十五","f":"七言绝句","c":["丱角春明入塾年，丈人摩我道崭然。","恍从魏晋纷纭后，为溯黄农浩渺前。"]},{"t":"己亥杂诗 其三十六","f":"七言绝句","c":["多君媕雅数论心，文字缘同骨肉深。","别有樽前挥涕语，英雄迟暮感黄金。"]},{"t":"己亥杂诗 其三十七","f":"七言绝句","c":["三十年华四牡腓，每谈宦辙壮怀飞。","樽前第一倾心听，兕甲楼船海外归。"]},{"t":"己亥杂诗 其四十","f":"七言绝句","c":["北方学者君第一，江左所闻君毕闻。","土厚水深词气重，烦君他日定吾文。"]},{"t":"己亥杂诗 其四十一","f":"七言绝句","c":["子云识字似相如，记得前年隔巷居。","忙杀奚童传拓本，一行翠墨一封书。"]},{"t":"己亥杂诗 其四十二","f":"七言绝句","c":["夹袋搜罗海内空，人才毕竟恃宗工。","笥河寂寂覃溪死，此席今时定属公。"]},{"t":"己亥杂诗 其四十三","f":"七言绝句","c":["联步朝天笑语馨，佩声耳畔尚泠泠。","遥知下界觇乾象，此夕银潢少客星。"]},{"t":"己亥杂诗 其四十五","f":"七言绝句","c":["眼前二万里风雷，飞出胸中不费才。","枉破期门佽飞胆，至今骇道遇仙回。"]},{"t":"己亥杂诗 其四十六","f":"七言绝句","c":["彤墀小立缀鹓鸾，金碧初阳当画看。","一队佽飞争识我，健儿身手此文官。"]},{"t":"己亥杂诗 其四十七","f":"七言绝句","c":["终贾华年气不平，官书许读兴纵横。","荷衣便识西华路，至竟虫鱼了一生。"]},{"t":"己亥杂诗 其四十八","f":"七言绝句","c":["万事源头必正名，非同综核汉公卿。","时流不沮狂生议，侧立东华儜佩声。"]},{"t":"己亥杂诗 其四十九","f":"七言绝句","c":["东华飞辩少年时，伐鼓撞钟海内知。","牍尾但书臣向校，头衔不称杀其词。"]},{"t":"己亥杂诗 其五十一","f":"七言绝句","c":["客星烂烂照天潢，许署头衔著作郎。","翠墨未乾仙字蚀，云烟半榻掖门旁。"]},{"t":"己亥杂诗 其五十二","f":"七言绝句","c":["齿如编贝汉东方，不学咿嚘况对扬。","屋瓦自惊天自笑，丹毫圆折露华瀼。"]},{"t":"己亥杂诗 其五十三","f":"七言绝句","c":["半生中外小回翔，樗丑翻成恋太阳。","挥手唐朝八司马，头衔老署退锋郎。"]},{"t":"己亥杂诗 其五十四","f":"七言绝句","c":["科以人重科益重，人以科传人可知。","本朝四十九科矣，搜集科名意在斯。"]},{"t":"己亥杂诗 其五十五","f":"七言绝句","c":["手校斜方百叶图，官书似此古今无。","只今绝学真成绝，册府苍凉六幕孤。"]},{"t":"己亥杂诗 其五十六","f":"七言绝句","c":["孔壁微茫坠绪穷，笙歌绛帐启宗风。","至今守定东京本，两庑如何阙马融？"]},{"t":"己亥杂诗 其五十七","f":"七言绝句","c":["姬周史统太销沈，况复炎刘古学瘖。","崛起有人扶左氏，千秋功罪总刘歆。"]},{"t":"己亥杂诗 其五十八","f":"七言绝句","c":["张杜西京说外家，斯文吾述段金沙。","导河积石归东海，一字源流奠万哗。"]},{"t":"己亥杂诗 其六十","f":"七言绝句","c":["华年心力九分殚，泪渍蟫鱼死不乾。","此事千秋无我席，毅然一炬为归安。"]},{"t":"己亥杂诗 其六十一","f":"七言绝句","c":["轩后孤虚纵莫寻，汉官戊己两言深。","著书不为丹铅误，中有风雷老将心。"]},{"t":"己亥杂诗 其六十四","f":"七言绝句","c":["熙朝仕版快茹征，五倍金元十倍明。","扬扢千秋儒者事，汉官仪后一书成。"]},{"t":"己亥杂诗 其六十五","f":"七言绝句","c":["文侯官冕听高歌，少作精严故不磨。","诗渐凡庸人可想，侧身天地我蹉跎。"]},{"t":"己亥杂诗 其六十六","f":"七言绝句","c":["西京别火位非高，薄有遗闻琐且劳。","只算初识镜背字，敢陈法物诂球刀。"]},{"t":"己亥杂诗 其六十七","f":"七言绝句","c":["十仞书仓郁且深，为夸目录散黄金。","吴回一怒知天意，无复龙威禹穴心。"]},{"t":"己亥杂诗 其六十九","f":"七言绝句","c":["吾祖平生好孟坚，丹黄郑重万珠圆。","不才窃比刘公是，请肄班香再十年。"]},{"t":"己亥杂诗 其七十","f":"七言绝句","c":["麟经断烂炎刘始，幸有兰台聚秘文。","解道何休逊班固，眼前同志只朱云。"]},{"t":"己亥杂诗 其七十二","f":"七言绝句","c":["少年薄录睨千秋，过目云烟浩不收。","一任汤汤沦泗水，九金万祀属成周。"]},{"t":"己亥杂诗 其七十五","f":"七言绝句","c":["不能古雅不幽灵，气体难跻作者庭。","毁杀流传遗下女，自障纨扇过旗亭。"]},{"t":"己亥杂诗 其七十六","f":"七言绝句","c":["文章合有老波澜，莫作鄱阳夹漈看。","五十年中言定验，苍茫六合此微官。"]},{"t":"己亥杂诗 其七十七","f":"七言绝句","c":["厚重虚怀见古风，车裀五度照门东。","我焚文字公焚疏，补纪交情为纪公。"]},{"t":"己亥杂诗 其七十八","f":"七言绝句","c":["狂禅辟尽礼天台，棹臂琉璃屏上回。","不是瓶笙花影夕，鸠摩枉译此经来。"]},{"t":"己亥杂诗 其七十九","f":"七言绝句","c":["手扪千轴古琅玕，笃信男儿识字难。","悔向侯王作宾客，廿篇鸿烈赠刘安。"]},{"t":"己亥杂诗 其八十","f":"七言绝句","c":["夜思师友泪滂沱，光影犹存急网罗。","言行较详官阀略，报恩如此疚心多。"]},{"t":"己亥杂诗 其八十一","f":"七言绝句","c":["历劫如何报佛恩，尘尘文字以为门。","遥知法会灵山在，八部天龙礼我言。"]},{"t":"己亥杂诗 其八十二","f":"七言绝句","c":["龙树灵根派别三，家家楖栗不能担。","我书唤作三桠记，六祖天台共一龛。"]},{"t":"己亥杂诗 其八十三","f":"七言绝句","c":["只筹一缆十夫多，细算千艘渡此河。","我亦曾穈太仓粟，夜闻邪许泪滂沱！"]},{"t":"己亥杂诗 其八十四","f":"七言绝句","c":["白面儒冠已问津，生涯只羡五侯宾。","萧萧黄叶空村畔，可有拥书闭户人？"]},{"t":"己亥杂诗 其八十五","f":"七言绝句","c":["津梁条约遍南东，谁遣藏春深坞逢？","不枉人呼莲幕客，碧纱幮护阿芙蓉。"]},{"t":"己亥杂诗 其八十六","f":"七言绝句","c":["鬼灯对对散秋萤，落魄参军泪眼荧。","何不专城花县去？","春眠寒食未曾醒。"]},{"t":"己亥杂诗 其八十八","f":"七言绝句","c":["河干劳问又江干，恩怨他时邸报看。","怪道乌台牙放早，几人怒马出长安。"]},{"t":"己亥杂诗 其八十九","f":"七言绝句","c":["学羿居然有羿风，千秋何可议逢蒙？","绝怜羿道无消息，第一亲弯射羿功。"]},{"t":"己亥杂诗 其九十","f":"七言绝句","c":["过百由旬烟水长，释迦老子怨津梁。","声闻闭眼三千劫，悔慕人天大法王。"]},{"t":"己亥杂诗 其九十一","f":"七言绝句","c":["北俊南孊气不同，少能炙毂老能聪。","可知销尽劳生骨，即在方言两卷中。"]},{"t":"己亥杂诗 其九十二","f":"七言绝句","c":["不容水部赋清愁，新拥牙旗拜列侯。","我替梅花深颂祷，明年何逊守扬州。"]},{"t":"己亥杂诗 其九十三","f":"七言绝句","c":["金銮并砚走龙蛇，无分同探阆苑花。","十一年来春梦冷，南游且吃玉川茶。"]},{"t":"己亥杂诗 其九十四","f":"七言绝句","c":["黄金脱手赠椎埋，屠狗无悰百计乖。","侥幸故人仍满眼，猖狂乞食过江淮。"]},{"t":"己亥杂诗 其九十五","f":"七言绝句","c":["大宇东南久寂寥，甄陀罗出一枝箫。","箫声容与渡淮去，怀上魂须七日招。"]},{"t":"己亥杂诗 其九十七","f":"七言绝句","c":["天花拂袂著难销，始愧声闻力未超。","青史他年烦点染，定功四纪遇灵箫。"]},{"t":"己亥杂诗 其九十八","f":"七言绝句","c":["一言恩重降云霄，魔劫成尘感不销。","未免初禅怯花影，梦回持偈谢灵箫。"]},{"t":"己亥杂诗 其一○○","f":"七言绝句","c":["坐我三熏三沐之，悬崖撒手别卿时。","不留后约将人误，笑指河阳镜里丝。"]},{"t":"己亥杂诗 其一○一","f":"七言绝句","c":["美人才调信纵横，我亦当筳拜盛名。","一笑劝君输一著，非将此骨媚公卿。"]},{"t":"己亥杂诗 其一○三","f":"七言绝句","c":["梨园爨本募谁修，亦是风花一代愁。","我替尊前深惋惜，文人珠玉女儿喉。"]},{"t":"己亥杂诗 其一○四","f":"七言绝句","c":["河汾房杜有人疑，名位千秋处士卑。","一事平生无齮龁，但开风气不为师。"]},{"t":"己亥杂诗 其一○五","f":"七言绝句","c":["生还重喜酹金焦，江上骚魂亦可招。","隔岸故人如未死，清樽读曲是明朝。"]},{"t":"己亥杂诗 其一○六","f":"七言绝句","c":["西来白浪打旌旗，万舶安危总未知。","寄语瞿塘江上贾，收帆好趁顺风时。"]},{"t":"己亥杂诗 其一○七","f":"七言绝句","c":["少年揽辔澄清意，倦矣应怜缩手时。","今日不挥闲涕泪，渡江只怨别蛾眉。"]},{"t":"己亥杂诗 其一○八","f":"七言绝句","c":["六月十五别甘泉，是夕丹徒风打船。","风定月出半江白，江上女郎眠未眠？"]},{"t":"己亥杂诗 其一○九","f":"七言绝句","c":["四海流传百轴刊，皤皤国老尚神完。","谈经忘却三公贵，只作先秦伏胜看。"]},{"t":"己亥杂诗 其一一○","f":"七言绝句","c":["蜀冈一老抱哀弦，阅尽词场意惘然。","绝似琵琶天宝后，江南重遇李龟年。"]},{"t":"己亥杂诗 其一一一","f":"七言绝句","c":["家公旧治我曾游，只晓梅村与凤洲。","收拾遗文浩无涘，东南一部小阳秋。"]},{"t":"己亥杂诗 其一一二","f":"七言绝句","c":["七里虹桥腐草腥，歌钟词赋两飘零。","不随天市为消长，文字光芒聚德星。"]},{"t":"己亥杂诗 其一一四","f":"七言绝句","c":["诗人瓶水与谟觞，郁怒清深两擅场。","如此高才胜高第，头衔追赠薄三唐。"]},{"t":"己亥杂诗 其一一五","f":"七言绝句","c":["荷衣说艺斗心兵，前辈须眉照座清。","收拾遗闻归一派，百年终恃小门生。"]},{"t":"己亥杂诗 其一一六","f":"七言绝句","c":["中年才子耽丝竹，俭岁高人厌薜萝。","两种情怀皆可谅，阳秋贬笔未宜多。"]},{"t":"己亥杂诗 其一一八","f":"七言绝句","c":["麟趾袅蹄式可寻，何须番舶献其琛？","汉家平淮书难续，且仿齐梁铸饼金。"]},{"t":"己亥杂诗 其一一九","f":"七言绝句","c":["作赋曾闻纸贵夸，谁令此纸遍京华？","不行官钞行私钞，名目何人饷史家？"]},{"t":"己亥杂诗 其一二一","f":"七言绝句","c":["荒青无缝种交加，月费牛溲定几车？","只是场师消遣法，不求秋实不看花。"]},{"t":"己亥杂诗 其一二二","f":"七言绝句","c":["六朝古黛梦中衡，无福秦淮放棹行。","想见钟山两才子，词锋落月互纵横。"]},{"t":"己亥杂诗 其一二四","f":"七言绝句","c":["残客津梁握手欷，多君郑重问乌衣。","故家自怨风流歇，肯骂无情燕子飞。"]},{"t":"己亥杂诗 其一二六","f":"七言绝句","c":["不容儿辈妄谈兵，镇物何妨一矫情。","别有狂言谢时望，东山妓即是苍生。"]},{"t":"己亥杂诗 其一二七","f":"七言绝句","c":["汉代神仙玉作堂，六朝文苑李男香。","过江子弟倾风采，放学归来祀卫郎。"]},{"t":"己亥杂诗 其一二九","f":"七言绝句","c":["陶潜诗喜说荆轲，想见停云发浩歌。","吟到恩雠心事涌，江湖侠骨恐无多。"]},{"t":"己亥杂诗 其一三一","f":"七言绝句","c":["陶潜磊落性情温，冥报因他一饭恩。","颇觉少陵诗吻薄，但言朝叩富儿门。"]},{"t":"己亥杂诗 其一三二","f":"七言绝句","c":["将左晨星一炬存，鱼龙光怪百千吞。","迢迢望气中原夜，又有湛卢剑倚门。"]},{"t":"己亥杂诗 其一三三","f":"七言绝句","c":["过江籍甚颜光禄，又作山中老树看。","赖是元龙楼百尺，雄谈夜半斗牛寒。"]},{"t":"己亥杂诗 其一三五","f":"七言绝句","c":["偶赋凌云偶倦飞，偶然闲慕遂初衣。","偶逢锦瑟家人问，便说寻春为汝归。"]},{"t":"己亥杂诗 其一三六","f":"七言绝句","c":["万卷书生飒爽来，梦中喜极故人回。","湖山旷劫三吴地，何日重生此霸才？"]},{"t":"己亥杂诗 其一三八","f":"七言绝句","c":["今日闲愁为洞庭，茶花凝想吐芳馨。","山人生死无消息，梦断查湾一角青。"]},{"t":"己亥杂诗 其一三九","f":"七言绝句","c":["玉立长身宋广文，常州重到忽思君。","遥怜屈贾英灵地，朴学奇才张一军。"]},{"t":"己亥杂诗 其一四○","f":"七言绝句","c":["太湖七十溇为墟，三泖圆斜各有初。","耻与蛟龙竟升斗，一编聊献郏侨书。"]},{"t":"己亥杂诗 其一四二","f":"七言绝句","c":["少年哀艳杂雄奇，暮气颓唐不自知。","哭过支硎山下路，重钞梅冶一奁诗。"]},{"t":"己亥杂诗 其一四三","f":"七言绝句","c":["温良阿者泪涟涟，能说吾家六十年。","见面恍疑悲母在，报恩祝乳后昆贤。"]},{"t":"己亥杂诗 其一四四","f":"七言绝句","c":["天教梼杌降家门，骨肉荆榛不可论。","赖是本支调护力，若敖不馁怙深恩。"]},{"t":"己亥杂诗 其一四五","f":"七言绝句","c":["径山一疏吼寰中，野烧苍凉悼达公。","何处复求龙象力，金光明照浙西东。"]},{"t":"己亥杂诗 其一四七","f":"七言绝句","c":["道场馣馤雨花天，长水宗风在目前。","一任拣机参活句，莫将文字换狂禅。"]},{"t":"己亥杂诗 其一四八","f":"七言绝句","c":["一脉灵长四叶貂，谈经门祚郁岧峣。","儒林几见传苗裔？","此伏高邮冠本朝。"]},{"t":"己亥杂诗 其一五○","f":"七言绝句","c":["里门风俗尚敦庞，年少争为齿德降。","桑梓温恭名教始，天涯何处不家江？"]},{"t":"己亥杂诗 其一五一","f":"七言绝句","c":["小别湖山劫外天，生还如證第三禅。","台宗晤后无来去，人道苍茫十四年。"]},{"t":"己亥杂诗 其一五三","f":"七言绝句","c":["亲朋岁月个萧闲，情话缠绵礼数删。","喜尽东华尘土否？","一秋十日九湖山。"]},{"t":"己亥杂诗 其一五四","f":"七言绝句","c":["高秋那得吴虹生，成轺西子湖边行。","一丘一壑我前导，重话东华送我情。"]},{"t":"己亥杂诗 其一五六","f":"七言绝句","c":["家住钱塘四百春，匪将门阀傲江滨。","一州典故闲徵遍，撰杖观涛得几人？"]},{"t":"己亥杂诗 其一五七","f":"七言绝句","c":["问我清游何日最，木樨风外等秋潮。","忽有故人心上过，乃是虹生与子潇。"]},{"t":"己亥杂诗 其一五八","f":"七言绝句","c":["灵鹫高华夜吐云，山凹指点旧家坟。","千秋名教吾谁愧？","愧读羲之誓墓文。"]},{"t":"己亥杂诗 其一五九","f":"七言绝句","c":["乡国论文集古欢，幽人三五薜萝看。","从知阆苑桃花色，不及溪松耐岁寒。"]},{"t":"己亥杂诗 其一六○","f":"七言绝句","c":["眼前石屋著书象，三世十方齐现身。","各搦著书一枝笔，各有洞天石屋春。"]},{"t":"己亥杂诗 其一六二","f":"七言绝句","c":["振绮堂中万轴书，乾嘉九野有谁如？","季方玉粹元方死，握手城东问蠹鱼。"]},{"t":"己亥杂诗 其一六三","f":"七言绝句","c":["与吾同祖砚北者，仁愿如兄壮岁亡。","从此与谁谈古处？","马婆巷外立斜阳。"]},{"t":"己亥杂诗 其一六四","f":"七言绝句","c":["醰醰诸老惬瞻衣，父齿随行亦未稀。","各有清名闻海内，春来各自典朝衣。"]},{"t":"己亥杂诗 其一六六","f":"七言绝句","c":["震旦狂禅沸不支，一灯慧命续如丝。","灵山未歇宗风歇，已过庞家日眚时。"]},{"t":"己亥杂诗 其一七三","f":"七言绝句","c":["碧涧重来荐一毛，杉楠喜比往时高。","故人地下仍相护，驱逐狐狸赖尔曹。"]},{"t":"己亥杂诗 其一七四","f":"七言绝句","c":["志乘英灵琐屑求，岂其落笔定阳秋？","百年子姓殷勤意，忍说挑灯为应酬。"]},{"t":"己亥杂诗 其一七六","f":"七言绝句","c":["俎脍飞沉竹肉喧，侍郎十日敞清尊。","东南不可无斯乐，濡笔亲题第四园。"]},{"t":"己亥杂诗 其一七八","f":"七言绝句","c":["儿谈梵夹婢谈兵，消息都防老父惊。","赖是摇鞭吟好句，流传乡里只诗名。"]},{"t":"己亥杂诗 其一七九","f":"七言绝句","c":["吴郎与我不相识，我识吴郎拂画看。","此外若容添一语，含元殿里觅长安。"]},{"t":"己亥杂诗 其一八○","f":"七言绝句","c":["科名掌故百年知，海岛畴人奉大师。","如此奇才终一令，蠹鱼零落我归时。"]},{"t":"己亥杂诗 其一八二","f":"七言绝句","c":["秋风张翰计蹉跎，红豆年年掷逝波。","误我归期知几许？","蟾圆十一度无多。"]},{"t":"己亥杂诗 其一八三","f":"七言绝句","c":["拊心消息过江淮，红泪淋浪避客揩。","千古知言汉武帝，人难再得始为佳。"]},{"t":"己亥杂诗 其一八四","f":"七言绝句","c":["小楼青对凤凰山，山影低徊黛影间。","今日当窗一奁镜，空王来證鬓丝班。"]},{"t":"己亥杂诗 其一八五","f":"七言绝句","c":["娇小温柔播六亲，兰姨琼姊各沾巾。","九泉肯受狂生誉？","艺是针神貌洛神。"]},{"t":"己亥杂诗 其一八六","f":"七言绝句","c":["阿娘重见话遗徽，病骨前秋盼我归。","欲寄无因今补赠，汗巾钞袋枕头衣。"]},{"t":"己亥杂诗 其一八七","f":"七言绝句","c":["云英未嫁损华年，心绪曾凭阿母传。","偿得三生幽怨否？","许侬亲对玉棺眠。"]},{"t":"己亥杂诗 其一八八","f":"七言绝句","c":["杭州风俗闹兰盆，绿蜡金炉梵唱繁。","我说天台三字偈，胜娘膜拜礼沙门。"]},{"t":"己亥杂诗 其一八九","f":"七言绝句","c":["残绒堆积绣窗间，慧婢商量赠指环。","但乞崔徽遗像去，重摹一帧供秋山。"]},{"t":"己亥杂诗 其一九○","f":"七言绝句","c":["昔年诗卷驻精魂，强续狂游拭涕痕。","拉得藕花衫子婢，篮舆仍出涌金门。"]},{"t":"己亥杂诗 其一九二","f":"七言绝句","c":["花神祠与水仙祠，欲订源流愧未知。","但向西泠添石刻，骈文撰出女郎碑。"]},{"t":"己亥杂诗 其一九九","f":"七言绝句","c":["野冬修竹欲连天，苦费西邻买笋钱。","此是商鞅垦土令，不同凿空误开边。"]},{"t":"己亥杂诗 其二○○","f":"七言绝句","c":["灵箫合贮此灵山，意思精微窈窕间。","区壑无双人地称，我无拙笔到眉弯。"]},{"t":"己亥杂诗 其二○二","f":"七言绝句","c":["料理空山颇费才，文心兼似画家来。","矮茶密致高松独，记取先生亲手栽。"]},{"t":"己亥杂诗 其二○四","f":"七言绝句","c":["可惜天南无此花，腰身略似海塘斜。","难忘槐市街南宅，小疏群芳稿一车。"]},{"t":"己亥杂诗 其二○五","f":"七言绝句","c":["可惜天南无此花，丽情还比牡丹奢。","难忘西掖归来早，赠与妆台满镜霞。"]},{"t":"己亥杂诗 其二○六","f":"七言绝句","c":["不是南天无此花，北肥南瘦二分差。","愿移北地胭脂社，来问南朝油壁车。"]},{"t":"己亥杂诗 其二○七","f":"七言绝句","c":["弱冠寻方数岁华，玲珑万玉嫭交加。","难忘细雨红泥寺，湿透春裘倚此花。"]},{"t":"己亥杂诗 其二○八","f":"七言绝句","c":["女墙百雉乱红酣，遗爱真同召伯甘。","记得花阴文宴屡，十年春梦寺门南。"]},{"t":"己亥杂诗 其二○九","f":"七言绝句","c":["空山徙倚倦游身，梦见城西阆苑春。","一骑传笺朱邸晚，临风递与缟衣人。"]},{"t":"己亥杂诗 其二一○","f":"七言绝句","c":["缱绻依人慧有馀，长安俊物最推渠。","故侯门第歌钟歇，犹办晨餐二寸鱼。"]},{"t":"己亥杂诗 其二一四","f":"七言绝句","c":["男儿解读韩愈诗，女儿好读姜夔词。","一家倘许圆鸥梦，昼课男儿夜女儿。"]},{"t":"己亥杂诗 其二一五","f":"七言绝句","c":["倘容我老半锄边，不要公卿寄奉钱。","一事避君君匿笑，刘郎才气亦求田。"]},{"t":"己亥杂诗 其二一七","f":"七言绝句","c":["回肠荡气感精灵，座客苍凉半酒醒。","自别吴郎高咏减，珊瑚击碎有谁听？"]},{"t":"己亥杂诗 其二一八","f":"七言绝句","c":["随身百轴字平安，身世无如屠钓宽。","耻学赵家臣宰例，归来香火乞祠官。"]},{"t":"己亥杂诗 其二一九","f":"七言绝句","c":["何肉周妻业并深，台宗古辙幸窥寻。","偷闲颇异凡夫法，流水池塘一观心。"]},{"t":"己亥杂诗 其二二一","f":"七言绝句","c":["西墙枯树态纵横，奇古全凭一臂撑。","烈士暮年宜学道，江关词赋笑兰成。"]},{"t":"己亥杂诗 其二二二","f":"七言绝句","c":["秋光明媚似春光，重九尊前草树香。","可记前年宝藏寺，西山暮雨怨吴郎。"]},{"t":"己亥杂诗 其二二四","f":"七言绝句","c":["莱菔生儿荠有孙，离批秋霰委黄昏。","青松心事成无赖，只阅前山野烧痕。"]},{"t":"己亥杂诗 其二二五","f":"七言绝句","c":["银烛秋堂独听心，隔帘谁报雨沉沉？","明朝不许沿溪赏，已没溪桥一尺深。"]},{"t":"己亥杂诗 其二二七","f":"七言绝句","c":["剩水残山意度深，平生几緉屐难寻。","栽花郑重看花约，此是刘郎迟暮心。"]},{"t":"己亥杂诗 其二二八","f":"七言绝句","c":["复墅拓墅祈墅了，吾将北矣乃图南。","无妻怕学林逋独，有子肯为王霸惭？"]},{"t":"己亥杂诗 其二二九","f":"七言绝句","c":["从今誓学六朝书，不肄山阴肄隐居。","万古焦山一痕石，飞升有数此权舆。"]},{"t":"己亥杂诗 其二三○","f":"七言绝句","c":["二王只合为奴仆，何况唐碑八百通。","欲与此铭分浩逸，北朝差许郑文公。"]},{"t":"己亥杂诗 其二三一","f":"七言绝句","c":["九流触手意纵横，极动当筵炳烛情。","若使鲁戈真在手，斜阳只乞照书城。"]},{"t":"己亥杂诗 其二三二","f":"七言绝句","c":["诗谶吾生信有之，预怜夜雨闭门时。","三更忽轸哀鸿思，九月无襦淮水湄。"]},{"t":"己亥杂诗 其二三三","f":"七言绝句","c":["燕兰识字尚聪明，难遣当筵迟暮情。","且莫空山听雨去，有人花底祝长生。"]},{"t":"己亥杂诗 其二三四","f":"七言绝句","c":["连宵灯火宴秋堂，绝色秋花各断肠。","又被北山猿鹤笑，五更浓挂一帆霜。"]},{"t":"己亥杂诗 其二三五","f":"七言绝句","c":["美人信有错刀投，不负张衡咏四愁。","爇罢心香屡回顾，古时明月照杭州。"]},{"t":"己亥杂诗 其二三六","f":"七言绝句","c":["阻风无酒倍消魂，况是残秋岸柳髡。","赖有阿咸情话好，一帆冷雨过娄门。"]},{"t":"己亥杂诗 其二三八","f":"七言绝句","c":["拟策孤筇避冶游，上方一塔俯清秋。","太湖夜照山灵影，顽福甘心让虎丘。"]},{"t":"己亥杂诗 其二四○","f":"七言绝句","c":["濯罢鲛绡镜槛凉，无端重试午时妆。","新诗急记销魂事，分与胭脂一掬汤。"]},{"t":"己亥杂诗 其二四一","f":"七言绝句","c":["少年尊隐有高文，猿鹤真堪张一军。","难向史家搜比例，商量出处到红裙。"]},{"t":"己亥杂诗 其二四三","f":"七言绝句","c":["怕听花间惜别词，伪留片语定来期。","秦邮驿近江潮远，是剔银灯诅我时。"]},{"t":"己亥杂诗 其二四四","f":"七言绝句","c":["停帆预卜酒杯深，十日无须逆旅金。","莫怨津梁为客久，天涯有弟话秋心。"]},{"t":"己亥杂诗 其二四五","f":"七言绝句","c":["豆蔻芳温启瓠犀，伤心前度语重提。","牡丹绝色三春暖，岂是梅花处士妻？"]},{"t":"己亥杂诗 其二四六","f":"七言绝句","c":["对人才调若飞仙，词令聪华四座传。","撑住东南金粉气，未须料理五湖船。"]},{"t":"己亥杂诗 其二四七","f":"七言绝句","c":["鹤背天风堕片言，能苏万古落花魂。","征衫不渍寻常泪，此是平生未报恩。"]},{"t":"己亥杂诗 其二四九","f":"七言绝句","c":["何须宴罢始留髡，绛蜡床前款一尊。","姊妹隔花催送客，尚拈罗带不开门。"]},{"t":"己亥杂诗 其二五○","f":"七言绝句","c":["去时栀子压犀簪，次第寒花掐到今。","谁分江湖摇落后，小屏红烛话冬心。"]},{"t":"己亥杂诗 其二五一","f":"七言绝句","c":["盘堆霜实擘庭榴，红似相思绿似愁。","今夕灵飞何甲子？","上清斋设记心头。"]},{"t":"己亥杂诗 其二五二","f":"七言绝句","c":["风云才略已消磨，甘隶妆台伺眼波。","为恐刘郎英气尽，卷帘梳洗望黄河。"]},{"t":"己亥杂诗 其二五三","f":"七言绝句","c":["玉树坚牢不病身，耻为娇喘与轻颦。","天花岂用铃幡护，活色生香五百春。"]},{"t":"己亥杂诗 其二五四","f":"七言绝句","c":["眉痕英绝语谡谡，指挥小婢带韬略。","幸汝生逢清晏时，不然剑底桃花落。"]},{"t":"己亥杂诗 其二五五","f":"七言绝句","c":["凤泊鸾飘别有愁，三生花草梦苏州。","儿家门巷斜阳改，输与船娘住虎丘。"]},{"t":"己亥杂诗 其二五六","f":"七言绝句","c":["一自天钟第一流，年来花草冷苏州。","儿家心绪无人见，他日埋香要虎丘。"]},{"t":"己亥杂诗 其二五七","f":"七言绝句","c":["难凭肉眼识天人，恐是优昙偶现身。","故遣相逢当五浊，不然谁信上仙沦？"]},{"t":"己亥杂诗 其二五九","f":"七言绝句","c":["酾江作醅亦不醉，倾河解渴亦不醒。","我侬醉醒自有例，肯向渠侬侧耳听。"]},{"t":"己亥杂诗 其二六○","f":"七言绝句","c":["收拾风花倜荡诗，凌晨端坐一凝思。","勉求玉体长生诀，留报金闺国士知。"]},{"t":"己亥杂诗 其二六一","f":"七言绝句","c":["绝色呼他心未安，品题天女本来难。","梅魂菊影商量遍，忍作人间花草看。"]},{"t":"己亥杂诗 其二六二","f":"七言绝句","c":["臣朔家原有细君，司香燕姞略知文。","无须问我山中事，肯向花间领右君？"]},{"t":"己亥杂诗 其二六三","f":"七言绝句","c":["道蕴谈锋不落诠，耳根何福受清圆？","自知语乏烟霞气，枉负才名三十年。"]},{"t":"己亥杂诗 其二六四","f":"七言绝句","c":["喜汝文无一笔平，坠侬五里雾中行。","悲欢离合本如此，错怨蛾眉解用兵。"]},{"t":"己亥杂诗 其二六五","f":"七言绝句","c":["美人才地太玲珑，我亦阴符满腹中。","今日帘旌秋缥缈，长天飞去一秋鸿。"]},{"t":"己亥杂诗 其二六六","f":"七言绝句","c":["青鸟衔来双鲤鱼，自缄红泪请回车。","六朝文体闲徵遍，那有萧娘谢罪书？"]},{"t":"己亥杂诗 其二六七","f":"七言绝句","c":["电笑何妨再一回，忽逢玉女谏书来。","东王万八千骁尽，为报投壶乏箭才。"]},{"t":"己亥杂诗 其二七○","f":"七言绝句","c":["身世闲商酒半醺，美人胸有北山文。","平交百口悠悠辈，揖罢还期将相勋。"]},{"t":"己亥杂诗 其二七一","f":"七言绝句","c":["金釭花炉月如烟，空损秋闺一夜眠。","报道妆成来送我，避卿先上木兰船。"]},{"t":"己亥杂诗 其二七三","f":"七言绝句","c":["欲求缥缈反幽深，悔杀前翻拂袖心。","难学冥鸿不回首，长天飞过又遗音。"]},{"t":"己亥杂诗 其二七四","f":"七言绝句","c":["明知此浦定重过，其奈尊前百感何？","亦是今生未曾有，满襟清泪渡黄河。"]},{"t":"己亥杂诗 其二七五","f":"七言绝句","c":["绝业名山幸早成，更何方法遣今生？","从兹礼佛烧香罢，整顿全神注定卿。"]},{"t":"己亥杂诗 其二七八","f":"七言绝句","c":["阅历天花悟后身，为谁出定亦前因。","一灯古店斋心坐，不似云屏梦里人。"]},{"t":"己亥杂诗 其二七九","f":"七言绝句","c":["此身已坐在山泉，涓滴无由补大川。","急报东方两星使，灵山吐溜为粮船。"]},{"t":"己亥杂诗 其二八○","f":"七言绝句","c":["昭代恩光日月高，丞彝十器比球刀。","吉金打本千行在，敬拓斯文冠所遭。"]},{"t":"己亥杂诗 其二八三","f":"七言绝句","c":["曩将奄宅證淹中，肃肃微言謦欬逢。","肯拓同文门畔石，古心突过汉朝松。"]},{"t":"己亥杂诗 其二八四","f":"七言绝句","c":["江左吟坛百辈狂，谁知阙里是词场？","我从宅壁低徊听，丝竹千秋尚绕梁。"]},{"t":"己亥杂诗 其二八五","f":"七言绝句","c":["嘉庆文风在目前，记同京兆鹿鸣筵。","白头相见冬山路，谁惜荷衣两少年？"]},{"t":"己亥杂诗 其二八七","f":"七言绝句","c":["子云壮岁雕虫感，掷向洪流付太虚。","从此不挥闲翰墨，男儿当注壁中书。"]},{"t":"己亥杂诗 其二八八","f":"七言绝句","c":["倘作家书寄哲儿，淮阴重话七年情。","门前报有关山客，来听西斋夜雨声。"]},{"t":"己亥杂诗 其二八九","f":"七言绝句","c":["家有凌云百尺条，风烟陪护渐岧峣。","生儿只识秦碑字，脆弱芝兰笑六朝。"]},{"t":"己亥杂诗 其二九○","f":"七言绝句","c":["盗诗补诗还祭诗，子梅诗史何恢奇。","鄙人劝君割荣者，努力删诗壮盛时。"]},{"t":"己亥杂诗 其二九一","f":"七言绝句","c":["诗格摹唐字有棱，梅花官阁夜锼冰。","一门鼎盛亲风雅，不似苍茫杜少陵。"]},{"t":"己亥杂诗 其二九二","f":"七言绝句","c":["八岁梦到矍相国，今日五君来做主。","我欲射侯陈礼容，可惜行装无白羽。"]},{"t":"己亥杂诗 其二九三","f":"七言绝句","c":["忽向东山感岁华，恍如庾岭对横斜。","敢参黄面瞿昙句？","此是森森阙里花。"]},{"t":"己亥杂诗 其二九七","f":"七言绝句","c":["苍生气类古犹今，安用冥鸿物外吟。","不是九州同急难，尼山谁识怃然心？"]},{"t":"己亥杂诗 其二九八","f":"七言绝句","c":["九边烂熟等雕虫，远志真看小草同。","枉说健儿身手在，青灯夜雪阻山东。"]},{"t":"己亥杂诗 其三○一","f":"七言绝句","c":["艰危门户要人持，孝出贫家谚有之。","葆汝心光淳闷在，皇天竺胙总无私。"]},{"t":"己亥杂诗 其三○三","f":"七言绝句","c":["俭腹高谈我用忧，肯肩朴学胜封侯。","五经熟烂家常饭，莫似而翁歠九流。"]},{"t":"己亥杂诗 其三○四","f":"七言绝句","c":["图籍移徙肺腑家，而翁本学段金沙。","丹黄字字皆珍重，为裹青毡载一车。"]},{"t":"己亥杂诗 其三○六","f":"七言绝句","c":["家园黄熟半林柑，抛向筠笼载两三。","风雪迎裾好持赠，预教诗婢识江南。"]},{"t":"己亥杂诗 其三○七","f":"七言绝句","c":["从此青山共露车，断无只梦堕天涯。","黄梅淡冶山矾靓，犹及双清好到家。"]},{"t":"己亥杂诗 其三○八","f":"七言绝句","c":["六义亲闻鲤对时，及身删定答亲慈。","刬除风雪关山句，归到高堂好背诗。"]},{"t":"己亥杂诗 其三○九","f":"七言绝句","c":["论诗论画复论禅，三绝门风海内传。","可惜语儿溪畔路，白头无分棹归舷。"]},{"t":"己亥杂诗 其三一○","f":"七言绝句","c":["使君谈艺笔通神，斗大高阳酒国春。","消我关山风雪怨，天涯握手尽文人。"]},{"t":"己亥杂诗 其三一五","f":"七言绝句","c":["吟罢江山气不灵，万千种话一灯青。","忽然搁笔无言说，重礼天台七卷经。"]},{"t":"己亥杂诗 其八十七","f":"七言绝句","c":["故人横海拜将军，侧立南天未蒇勋。","我有阴符三百字，蜡丸难寄惜雄文。"]},{"t":"己亥杂诗 其四十四","f":"七言绝句","c":["霜毫掷罢倚天寒，任作淋漓淡墨看。","何敢自矜医国手，药方只贩古时丹。"]},{"t":"己亥杂诗 其一二五","f":"七言绝句","c":["九州生气恃风雷，万马齐喑究可哀。","我劝天公重抖擞，不拘一格降人才。"]},{"t":"己亥杂诗 其一二三","f":"七言绝句","c":["不论盐铁不筹河，独倚东南涕泪多。","国赋三升民一斗，屠牛那不胜栽禾？"]},{"t":"己亥杂诗 其二十八","f":"七言绝句","c":["不是逢人苦誉君，亦狂亦侠亦温文。","照人胆似秦时月，送我情如岭上云。"]},{"t":"吴山人文徵、沈书记锡东饯之虎邱","f":"七言绝句","c":["一天幽怨欲谁谙，词客如云气正酣。","我有箫心吹不得，落花风里别江南。"]},{"t":"梦中作四截句其二","f":"七言绝句","c":["黄金华发两飘萧，六九童心尚未消。","叱起海红帘底月，四厢花影怒于潮。"]},{"t":"漫感","f":"七言绝句","c":["绝域从军计惘然，东南幽恨满词笺。","一箫一剑平生意，负尽狂名十五年。"]},{"t":"咏史二首 其一","f":"七言律诗","c":["宣室今年起故侯，衔兼中外辖黄流。","金銮午夜闻乾惕，银汉千寻泻豫州。","猿鹤惊心悲皓月，鱼龙得意舞高秋。","云梯关外茫茫路，一夜吟魂万里愁。"]},{"t":"咏史","f":"七言律诗","c":["金粉东南十五州，万重恩怨属名流。","牢盆狎客操全算，团扇才人踞上游。","避席畏闻文字狱，著书都为稻粱谋。","田横五百人安在，难道归来尽列侯。"]},{"t":"夜坐其一","f":"七言律诗","c":["春夜伤心坐画屏，不如放眼入青冥。","一山突起丘陵妒，万籁无言帝座灵。","塞上似腾奇女气，江东久陨少微星。","从来不蓄湘累问，唤出嫦娥诗与听。"]},{"t":"夜坐其二","f":"七言律诗","c":["沉沉心事北南东，一睨人材海内空。","壮岁始参周史席，髫年惜堕晋贤风。","功高拜将成仙外，才尽回肠荡气中。","万一禅关砉然破，美人如玉剑如虹。"]},{"t":"逆旅题壁，次周伯恬原韵","f":"七言律诗","c":["名场阅历莽无涯，心史纵横自一家。","秋气不惊堂内燕，夕阳还恋路旁鸦。","东邻嫠老难为妾，古木根深不似花。","何日冥鸿踪迹遂，美人经卷葬年华。"]},{"t":"赋忧患","f":"五言律诗","c":["故物人寰少，犹蒙忧患俱。","春深恒作伴，宵梦亦先驱。","不逐年华改，难同逝水徂。","多情谁似汝？","未忍托禳巫。"]},{"t":"秋心","f":"七言律诗","c":["秋心如海复如潮，惟有秋魂不可招。","漠漠郁金香在臂，亭亭古玉佩当腰。","气寒西北何人剑，声满东南几处箫。","一川星斗烂无数，长天一月坠林梢。"]},{"t":"己亥杂诗 其一九六","f":"七言绝句","c":["一十三度溪花红，一百八下西溪钟。","卿家沧桑卿命短，渠侬不关关我侬。"]},{"t":"己亥杂诗 其一九七","f":"七言绝句","c":["一百八下西溪钟，一十三度溪花红。","是恩是怨无性相，冥祥记里魂朦胧。"]},{"t":"己亥杂诗 其九","f":"七言绝句","c":["翠微山在柘潭侧，此山有情惨难别。","薜荔风号义士魂，燕支土蚀佳人骨。"]},{"t":"己亥杂诗 其十六","f":"七言绝句","c":["弃妇丁宁嘱小姑，姑恩莫负百年劬。","米盐种种家常话，泪湿红裙未绝裾。"]},{"t":"己亥杂诗 其二十二","f":"七言绝句","c":["车中三观夕惕若，七岁灵文电熠若。","忏摩重起耳提若，三普贯珠累累若。"]},{"t":"己亥杂诗 其二十三","f":"七言绝句","c":["荒村有客抱蠹鱼，万一谈经引到渠。","终胜秋燐无姓氏，沙涡门外五尚书。"]},{"t":"己亥杂诗 其二十九","f":"七言绝句","c":["觥觥益阳风骨奇，壮年自定千首诗。","勇于自信故英绝，胜彼优孟俯仰为。"]},{"t":"己亥杂诗 其三十八","f":"七言绝句","c":["五十一人皆好我，八公送别益情亲。","他年卧听除书罢，冉冉修名独伤神。"]},{"t":"己亥杂诗 其三十九","f":"七言绝句","c":["朝借一经覆以簦，暮还一经龛已灯。","龙华相见再相谢，借经功德龙泉僧。"]},{"t":"己亥杂诗 其五十","f":"七言绝句","c":["千言只作卑之论，敢以虚怀测上公？","若问汉朝诸配享，少牢乞附孙叔通。"]},{"t":"己亥杂诗 其五十九","f":"七言绝句","c":["端门授命有云礽，一脉微言我敬承。","宿草敢祧刘礼部，东海绝学在毗陵。"]},{"t":"己亥杂诗 其六十二","f":"七言绝句","c":["古人制字鬼神泣，后人识字百忧集。","我不畏鬼复不忧，灵文夜补秋灯碧。"]},{"t":"己亥杂诗 其六十三","f":"七言绝句","c":["经有家法夙所重，诗无远诂独不用。","我心即是四始心，泬寥再发姬公梦。"]},{"t":"己亥杂诗 其六十八","f":"七言绝句","c":["北游不至独石口，东游不至卢龙关。","此记游耳非著作，马蹄蹀躞书生孱。"]},{"t":"己亥杂诗 其七十一","f":"七言绝句","c":["剔彼高山大川字，薄我玉箧金扃中。","从此九州不光怪，羽陵夜色春熊熊。"]},{"t":"己亥杂诗 其七十三","f":"七言绝句","c":["奇气一纵不可阖，此是借琐耗奇法。","奇则耗矣琐未休，眼前胪列成五岳。"]},{"t":"己亥杂诗 其七十四","f":"七言绝句","c":["登乙科则亡姓氏，官七品则亡姓氏。","夜奠三十九布衣，秋灯忽吐苍虹气。"]},{"t":"己亥杂诗 其九十九","f":"七言绝句","c":["能令公愠公复喜，扬州女儿名小云。","初弦相见上弦别，不曾题满杏黄裙。"]},{"t":"己亥杂诗 其一○二","f":"七言绝句","c":["网罗文献吾倦矣，选色谈空习性存。","江淮狂生知我者，绿笺百字铭其言。"]},{"t":"己亥杂诗 其一一三","f":"七言绝句","c":["公子有德宜置诸，有德公子毋忘诸。","我方乞籴忽诵此，箴铭磊落肝脾虚。"]},{"t":"己亥杂诗 其一一七","f":"七言绝句","c":["姬姜古妆不如市，赵女轻盈蹑锐屐。","侯王宗庙求元妃，徽音岂在纤厥趾？"]},{"t":"己亥杂诗 其一二○","f":"七言绝句","c":["促柱危弦太觉孤，琴边倦眼眄平芜。","香兰自判前因误，生不当门也被除。"]},{"t":"己亥杂诗 其一三四","f":"七言绝句","c":["五十一人忽少三，我闻陨涕江之南。","箧中都有旧墨迹，从此袭以玫瑰函。"]},{"t":"己亥杂诗 其一三七","f":"七言绝句","c":["故人有子尚饘粥，抱君等身大著作。","刘向而后此大宗，岂同陈晁竟目录。"]},{"t":"己亥杂诗 其一四一","f":"七言绝句","c":["铁师讲经门径仄，铁诗念佛颇得力。","似师毕竟胜狂禅，师今迟我莲花国。"]},{"t":"己亥杂诗 其一四六","f":"七言绝句","c":["有明像法披猖后，荷担如来两尊宿。","龙树马鸣齐现身，我闻大地狮子吼。"]},{"t":"己亥杂诗 其一四九","f":"七言绝句","c":["只将愧汗湿莱衣，毁极堂堂岁月迟。","世事沧桑心事定，此生一跌莫全非。"]},{"t":"己亥杂诗 其一五二","f":"七言绝句","c":["浙东虽秀太轻孱，北地雄奇或犷顽。","踏遍中华窥两界，无双毕竟是家山。"]},{"t":"己亥杂诗 其一五五","f":"七言绝句","c":["除却虹生忆黄子，曝衣忽见黄罗衫。","文章风谊细评度，岭南何减江之南？"]},{"t":"己亥杂诗 其一六一","f":"七言绝句","c":["如何从假入空法，君亦莫问我莫答。","若有自性互不成，互不成者谁佛刹？"]},{"t":"己亥杂诗 其一六五","f":"七言绝句","c":["我言送客非佛事，师言不送非佛智。","双照送是不送是，金光大地乔松寺。"]},{"t":"己亥杂诗 其一六七","f":"七言绝句","c":["曩向真州订古文，飞龙滂熹折纷纭。","经生家法从来异，拓本模糊且饷君。"]},{"t":"己亥杂诗 其一六八","f":"七言绝句","c":["闭门三日了何事，题图祝寿谀人诗。","双文单笔记序偈，突笔幸趁酒热时。"]},{"t":"己亥杂诗 其一六九","f":"七言绝句","c":["劘之道义拯之难，赏我出处好我书。","史公副墨问姓氏，屈指首寄虬髯吴。"]},{"t":"己亥杂诗 其一七一","f":"七言绝句","c":["猰貐猰貐厉牙齿，求覆我祖十世祀。","我请于帝诅于鬼，亚驼巫阳莅鸡豕。"]},{"t":"己亥杂诗 其一七二","f":"七言绝句","c":["书梦亚驼告有意，明年三月猰貐死。","大神羹枭殄枭子，焚香敬告少昊氏。"]},{"t":"己亥杂诗 其一七五","f":"七言绝句","c":["琼林何不积缗钱，物自低昂人自便。","我与徐公筹到此，朱提山竭亦无权。"]},{"t":"己亥杂诗 其一七七","f":"七言绝句","c":["藏书藏帖两高人，目录流传四十年。","师友凋徂心力倦，羽陵一记亦荆榛。"]},{"t":"己亥杂诗 其一八一","f":"七言绝句","c":["惠逆同门复同薮，谋臧不臧视朋友。","我兹怦然谋乃心，君已砉然脱诸口。"]},{"t":"己亥杂诗 其一九一","f":"七言绝句","c":["蟠夔小印镂珊瑚，小字高华出汉书。","原是狂生漫题赠，六朝碑例合镌无？"]},{"t":"己亥杂诗 其一九三","f":"七言绝句","c":["小婢口齿蛮复蛮，秋衫红泪潸复潸。","眉痕约略弯复弯，婢如夫人难复难。"]},{"t":"己亥杂诗 其一九四","f":"七言绝句","c":["女儿魂魄完复完，湖山秀气还复还。","炉香瓶卉残复残，他生重见艰复艰。"]},{"t":"己亥杂诗 其一九八","f":"七言绝句","c":["草创江东署羽陵，异书奇石小崚嶒。","十年松竹谁留守？","南渡飞扬是中兴。"]},{"t":"己亥杂诗 其二○一","f":"七言绝句","c":["此是春秋据乱作，升平太平视松竹。","何以功成文致之？","携箫飞上羽陵阁。"]},{"t":"己亥杂诗 其二○三","f":"七言绝句","c":["君家先茔邓尉侧，佳木生之杂绀碧。","不看人间顷刻花，他年管领风云色。"]},{"t":"己亥杂诗 其二一一","f":"七言绝句","c":["万绿无人嘒一蝉，三层阁子俯秋烟。","安排写集三千卷，料理看山五十年。"]},{"t":"己亥杂诗 其二一二","f":"七言绝句","c":["海西别墅吾息壤，羽陵三重拾级上。","明年俯看千树梅，飘飖亦是天际想。"]},{"t":"己亥杂诗 其二一三","f":"七言绝句","c":["此阁宜供天人师，檀香三尺博士为。","阮公施香孰施字？","徐公字似萧梁碑。"]},{"t":"己亥杂诗 其二一六","f":"七言绝句","c":["瑰癖消沉结习虚，一篇典宝古文无。","金灯出土苔花碧，又照徐陵读汉书。"]},{"t":"己亥杂诗 其二二○","f":"七言绝句","c":["皇初任土乃作贡，卅七亩山可才众。","媪神笑予无贫法，丹徒陆生言可用。"]},{"t":"己亥杂诗 其二二三","f":"七言绝句","c":["似笑山人不到家，争将晚节尽情夸。","三秋不陨芙蓉■，九月犹开窅窳花。"]},{"t":"己亥杂诗 其二二六","f":"七言绝句","c":["空观假观第一观，佛言世谛不可乱。","人生宛有去来今，卧听檐花落秋半。"]},{"t":"己亥杂诗 其二三七","f":"七言绝句","c":["杭州梅舌酸复甜，有笋名曰虎爪尖。","芼以苏州小橄榄，可敌北方冬菘腌。"]},{"t":"己亥杂诗 其二三九","f":"七言绝句","c":["阿咸从我十日游，遇管城子于虎丘。","有笔可橐不可投，簪笔致身公与侯。"]},{"t":"己亥杂诗 其二四二","f":"七言绝句","c":["谁肯甘心薄幸名，南舣北驾怨三生。","劳人只有空王谅，那向如花辨得明？"]},{"t":"己亥杂诗 其二四八","f":"七言绝句","c":["小语精微沥耳圆，况聆珠玉泻如泉。","一番心上温黁过，明镜明朝定少年。"]},{"t":"己亥杂诗 其二五八","f":"七言绝句","c":["云英化水景光新，略似骖鸾缥缈身。","一队画师齐敛手，只容心里贮秾春。"]},{"t":"己亥杂诗 其二六八","f":"七言绝句","c":["万一天填恨海平，羽陵安稳贮云英。","仙山楼阁寻常事，兜率甘迟十劫生。"]},{"t":"己亥杂诗 其二六九","f":"七言绝句","c":["美人捭阖计频仍，我佩阴符亦可凭。","绾就同心坚待辱，羽陵山下是西陵。"]},{"t":"己亥杂诗 其二七二","f":"七言绝句","c":["未济终焉心缥缈，百事翻从缺陷好。","吟道夕阳山外山，古今谁免馀情绕？"]},{"t":"己亥杂诗 其二七六","f":"七言绝句","c":["少年虽亦薄汤武，不薄秦皇与汉武。","设想英雄垂暮日，温柔不住住何乡？"]},{"t":"己亥杂诗 其二七七","f":"七言绝句","c":["客心今雨匿旧雨，江痕早潮收暮潮。","新欢且问黄婆渡，影事休提白傅桥。"]},{"t":"己亥杂诗 其二八一","f":"七言绝句","c":["少年无福过阙里，中年著书复求仕。","仕幸不成书幸成，乃敢斋祓告孔子。"]},{"t":"己亥杂诗 其二八二","f":"七言绝句","c":["少为贱士抱弗宣，状为祠曹默益坚。","议则不敢腰膝在，庑下一揖中夷然。"]},{"t":"己亥杂诗 其二八六","f":"七言绝句","c":["少年奇气称才华，登岱还浮八月搓。","我过东方亦无负，清尊三宿孔融家。"]},{"t":"己亥杂诗 其二九四","f":"七言绝句","c":["前车辙浅后车缩，两车勒马让先跃。","何况东阳绛灌年，贾生欀臂定礼乐。"]},{"t":"己亥杂诗 其二九五","f":"七言绝句","c":["古人用兵重福将，小说家名因果状。","不信古书愎用知，水厄淋漓黑貂丧。"]},{"t":"己亥杂诗 其二九六","f":"七言绝句","c":["天意若曰汝毋北，覆车南沙书卷湿。","汶阳风雨六幕黑，申以东平三尺雪。"]},{"t":"己亥杂诗 其二九九","f":"七言绝句","c":["任丘马首有筝琶，偶落吟鞭便驻车。","北望觚棱南望雁，七行狂草达京师。"]},{"t":"己亥杂诗 其三○○","f":"七言绝句","c":["房山一角露崚嶒，十二连桥夜有冰。","渐进城南天五尺，回灯不敢梦觚棱。"]},{"t":"己亥杂诗 其三○二","f":"七言绝句","c":["虽然大器晚年成，卓荦全凭弱冠争。","多识前言蓄其德，莫抛心力贸才名。"]},{"t":"己亥杂诗 其三○五","f":"七言绝句","c":["欲从太史窥春秋，勿向有字句虚求。","抱微言者太史氏，大义显显则予休。"]},{"t":"己亥杂诗 其三一一","f":"七言绝句","c":["画禅有女定清真，合配琳琅万轴身。","百里畿南风雪路，我来著手竟成春。"]},{"t":"己亥杂诗 其三一二","f":"七言绝句","c":["古愁莽莽不可说，化作飞仙忽奇阔。","江天如墨我飞还，折梅不畏蛟龙夺。"]},{"t":"己亥杂诗 其三一三","f":"七言绝句","c":["惠山秀气迎客舟，七十里外心先投。","惠山妆成要妆镜，惠泉那许东北流？"]},{"t":"己亥杂诗 其三一四","f":"七言绝句","c":["丹宝琼花海岸旁，羽陵山似峚之阳。","一家可惜仍烟火，未问仙人辟谷方。"]},{"t":"西郊落花歌","f":"古风","c":["西郊落花天下奇，古来但赋伤春诗，西郊车马一朝尽，定庵先生沽酒来赏之。","先生探春人不觉，先生送春人又嗤，呼朋亦得三四子，出城失色人皆痴。","如钱塘潮夜澎湃，如昆阳战晨披靡，如八万四千天女洗脸罢，齐向此地倾胭脂。","奇龙怪凤爱漂泊，琴高之鲤何反欲上天为？","玉皇宫中空若洗，三百六十界无一青蛾眉。","又如先生平生之忧患，恍惚怪诞百出难穷期。","先生读书尽三藏，最喜维摩卷里多清词，又闻净土落花深四寸，冥目观想犹神驰。","西方净国未可到，下笔绮语何漓漓，安得树有不尽之花更雨新好者，三百六十日常是落花时！"]},{"t":"辛巳除夕与彭同年同宿道观中，彭出平生诗，","f":"古风","c":["读之竟夜，遂书卷尾亦是三生影，同听一杵钟。","挑灯人海外，拔剑梦魂中。","雪色惮恩怨，诗声破苦空。","明朝客盈座，谁言去年踪。"]},{"t":"鹊踏枝 过人家废园作","f":"古风","c":["漠漠春芜春不住。","藤刺牵衣，碍却行人路。","偏是无情偏解舞。","濛濛扑面皆飞絮。","绣院深沈谁是主。","一朵孤花，墙角明如许。","莫怨无人来折取。","花开不合阳春暮。"]},{"t":"点绛唇 十月二日马上作","f":"古风","c":["一帽红尘，行来韦杜人家北。","满城风色，漠漠楼台隔。","目送飞鸿，景入长天灭。","关山绝，乱云千叠，江北江南雪。"]},{"t":"湘月","f":"古风","c":["天风吹我，堕湖山一角，果然清丽。","曾是东华生小客，回首苍茫无际。","屠狗功名，雕龙文卷，岂是平生意。","乡亲苏小，定应笑我非计。","才见一抹斜阳，半堤芳草，顿惹清愁起。","罗袜音尘何处觅，渺渺予怀孤寄。","怨去吹箫，狂来说剑，两样消魂味。","两般春梦，舻声荡入云水。"]},{"t":"暮雨谣三叠 其一","f":"五言绝句","c":["不雨怜生草，曾亲撷翠人。","林塘三百步，车去竟无尘。"]},{"t":"暮雨谣三叠 其二","f":"五言绝句","c":["雨气侵罗袜，泥痕黦画裳。","春阴太萧瑟，归费夕炉香。"]},{"t":"暮雨谣三叠 其三","f":"五言绝句","c":["想见明镫下，帘衣一桁单。","相思无十里，同此凤城寒。"]},{"t":"辛巳除夕与彭同年同宿道观中彭出平生诗读之竟夜遂书其卷尾","f":"五言律诗","c":["亦是三生影，同听一杵钟。","挑镫人海外，拔剑梦魂中。","雪色憺恩怨，诗声破苦空。","明朝客盈坐，谁信去年踪。"]},{"t":"汉朝儒生行","f":"古风","c":["汉朝儒生不青紫，二十高名动都市。","《易》通田何《书》欧阳，三十方补掌故史。","门寒地远性傥荡，出门无阶媚天子。","会当大河决酸枣，愿入薪楗三万矢。","路逢绛灌拜马首，拜则槃辟人不喜。","归来仰屋百喟生，著书时时说神鬼。","生不逢高皇骂儒冠，亦不遇灞陵轻少年。","爱读《武皇传》，不遇武皇祠神仙。","神仙解词赋，《大人》一秦凌云天。","枕中黄金岂无药，更生误读淮王篇。","自言汉家故事网罗尽，胸中语秘世莫传。","略传将军之客数言耳，不惜钳我歌当筵。","一歌使公惧，再歌使公悟，我歌无罪公无怒。","汉朝西海如郡县，蒲萄天马年年见。","匈奴左臂乌孙王，七译来同藁街宴。","武昭以还国威壮，狗监鹰媒尽边将。","出门攘臂攫牛羊，三载践更翻沮丧。","三十六城一城反，都护上言请勤远。","期门或怒或阴喜，喜者何心怒则愤。","关西籍甚良家子，卅年久绾军符矣。","不结椎埋儿，不长鸣珂里。","声名自震大荒西，饮马昆仑荡海水。","不共郅支生，愿逐楼兰死。","上书初到公卿惊，共言将军宜典丘。","麟生凤降岂有种，况乃一家中国犹弟兄。","旌旗五道从天落，小印如斗大如斛。","尽隶将军一臂呼，万人侧目千人诺。","山西少年感生泣，羽林群儿各努力。","共知汉主拔孤根，坐见孤根壮刘室。","不知何姓小侯瞋，不知何客惎将军。","将军内顾忽疑惧，功成定被他人分。","不如自亲求自附，飞书请隶嫖姚部。","上言乞禁兵，下言避贤路。","笑比高皇十八侯，自居虫达曾无羞。","此身愿爵关内老，黄金百斤聊可保。","呜呼！","汉家旧事无人知，南军北军颇有私。","北军似姑南似嫂，嫂疏姑戚群僮窥。","可怜旧事无人信，门户千秋几时定。","门户原非主上心，詄荡吾知汉皇圣。","是时书到甘泉夜，答诏徘徊未轻下。","密问三公是与非，沮者不坚语中罢。","庾词本冀公卿谅，末议微闻道涂骂。","拙哉某将军，非火胡自焚。","非蚕胡自缚，非虿胡自螫。","有舌胡自挢，有臂胡自掣。","军至矣，刺史迎，肥牛之腱万镬烹。","军过矣，掠童女，马踏燕支贱如土。","嬴家长城如一环，汉家长城衣带间。","嬴家正为汉家用，坐见入开仍出关。","入关马行疾，出关马无力。","丞华厩里芝草稀，水衡金贱苦乏绝。","卜式羊蹄尚无用，相如黄金定何益。","珠崖可弃例弃之，夜过茂陵闻太息。","汉家庙食果何人，未必卫霍无侪伦。","酹金失侯亦有命，人生那用多苦辛。","噫嚱！","人生那用长苦辛。","勿向人间老，老阅风霜亦枯槁。","千尺寒潭白日沈，将军之心如此深。","后世读书者，毋向兰台寻。","兰台能书汉朝事，不能尽书汉朝千百心，儒林丈人识此吟。"]},{"t":"暮春以事诣圆明园趋公既罢因览西郊形胜最后过澄怀园和内直友人春晚退直诗 其一","f":"五言律诗","c":["西郊富山水，天子驻青旂。","元气古来积，群灵咸是依。","九重阿阁外，一脉太行飞。","何必东南美，宸居静紫微。"]},{"t":"暮春以事诣圆明园趋公既罢因览西郊形胜最后过澄怀园和内直友人春晚退直诗 其二","f":"五言律诗","c":["一翠扑人冷，空濛溯却遥。","湖光飞阙外，宫月澹林梢。","春暮烟霞润，天和草木骄。","桃花零落处，上苑亦红潮。"]},{"t":"暮春以事诣圆明园趋公既罢因览西郊形胜最后过澄怀园和内直友人春晚退直诗 其三","f":"五言律诗","c":["恍惚西湖路，其如怅望何。","期门瞩威武，贱士感蹉跎。","囿沼输鱼跃，峰峦羡鸟过。","周阹新令在，不得睹卷阿。"]},{"t":"暮春以事诣圆明园趋公既罢因览西郊形胜最后过澄怀园和内直友人春晚退直诗 其四","f":"五言律诗","c":["掌故吾能说，雍乾溯以还。","禅心辟初地，小幸集汪班。","遂进群藩宴，兼怡圣母颜。","升平六十载，乃大启三山。"]},{"t":"暮春以事诣圆明园趋公既罢因览西郊形胜最后过澄怀园和内直友人春晚退直诗 其五","f":"五言律诗","c":["警跸闻传膳，枢廷述地方。","宸游兼武备，大典在官长。","禁额如云起，仙人隔仗望。","万重珊翠里，不数尚书郎。"]},{"t":"暮春以事诣圆明园趋公既罢因览西郊形胜最后过澄怀园和内直友人春晚退直诗 其六","f":"五言律诗","c":["此地求沿革，当年本合并。","林岚陪禁近，词庙仰勋名。","水榭分还壮，云廊改更清。","诸公齐努力，谁得似桐城。"]},{"t":"寒月吟 其一","f":"五言古诗","c":["夜起数山川，浩浩共月色。","不知何山青，不知何川白。","幽幽东南隅，似有偕隐宅。","下南一以望，终恋杭州路。","城里虽无家，城外却有墓。","相期买一丘，毋远故乡故。","而我屏见闻，而汝养幽素。","舟行百里间，须见墓门树。","南向发此言，恍欲双飞去。"]},{"t":"寒月吟 其二","f":"五言古诗","c":["双飞去未能，月浸衣裳湿。","秋焉静念之，劳生几时歇。","劳者本庸流，事事乏定识。","朴愚伤于家，放诞忌于国。","皇天误矜宠，付汝忧患物。","再拜何敢当，藉以战道力。","何期闺闱中，亦荷天眷别。","多难淬心光，黾勉共一室。","忧患吾故物，明月吾故人。","可隐不偕隐，有如月一轮。","心迹如此清，容光如此新。","我读先秦书，莱子有逸妻。","闺房以逸传，此名蹈者希。","勿慕厥名高，我知厥心悲。","定多不传事，子孙无由知。","岂但无由知，知之反涟洏。","羞登中垒传，耻勒度尚碑。","一逸虑患难，所全浩无涯。","一逸谢万古，冥冥不可追。","示君读书法，君慧肯三思。"]},{"t":"寒月吟 其三","f":"五言古诗","c":["我生受之天，哀乐恒过人。","我有平生交，外氏之懿亲。","自我慈母死，谁馈此翁贫。","江关邈消息，生死知无因。","八十罹饥寒，虽生犹僇民。","作梦来哑哑，心肝何清真。","翁自须发白，我如髫丱淳。","梦中既觞之，而复留遮之。","挽须搔爬之，磨墨揄揶之。","呼镫而烛之，论文而哗之。","阿母在旁坐，连连呼叔耶。","今朝无风雪，我泪浩如雪。","莫怪泪如雪，人生思幼日。"]},{"t":"寒月吟 其四","f":"五言古诗","c":["侵晓邻僧来，馈我佛前粥。","其香何清严，腊供今年足。","我因思杭州，不仅有三竺。","东城八九寺，寺寺皆修竹。","何年舍家去，慧业改所托。","掘笋慈风园，参茶东父屋。","钟鱼四围静，扫地洁如沐。","白昼为之长，倦骸为之肃。","供黄梅一枝，朝朝写《圆觉》。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其一","f":"五言古诗","c":["道力战万籁，微芒课其功。","不能胜十心，安能胜苍穹。","相彼鸾与凤，不栖枯枝松。","天神傥下来，清明可与通。","返听如有声，消息鞭愈聋。","死我信道笃，生我行神空。","障海使西流，挥日还于东。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其二","f":"五言古诗","c":["黔首本骨肉，天地本比邻。","一发不可牵，牵之动全身。","圣者胞与言，夫岂夸大陈。","四海变秋气，一室难为春。","宗周若蠢蠢，嫠纬烧为尘。","所以慨慷士，不得不悲辛。","看花忆黄河，对月思西秦。","贵官勿三思，以我为杞人。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其三","f":"五言古诗","c":["名埋孕异梦，秀句镌春心。","庄骚雨灵鬼，盘踞肝肠深。","古来不可兼，方寸我何任。","所以志为道，澹宕生微吟。","一箫与一笛，化作太古琴。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其四","f":"五言古诗","c":["我有秦时镜，窈窕龙鸾痕。","我有汉宫玉，触手犹生温。","我有墨九行，惊鸿若可扪。","玉皇忽公道，奇福三至门。","欲供三炷香，先消万古魂。","古春伴忧患，诘屈生酸黁。","且摺三千本，赠与人间存。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其五","f":"五言古诗","c":["朝从屠沽游，夕拉驺卒饮。","此意不可道，有若茹大鲠。","传闻智勇人，伤心自鞭影。","蹉跎复蹉跎，黄金满虚牝。","匣中龙剑光，一鸣四壁静。","夜夜辄一鸣，负汝汝难忍。","出门何茫茫，天心牖其逞。","既窥豫让桥，复瞰轵深井。","长跪奠一卮，风云扑人冷。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其六","f":"古风","c":["造化大痈痔，斯言韩柳共。","我思文人言，毋乃太惊众。","儒家守门户，家法毋徇纵。","事天如事亲，谁云小儿弄。","我身我不有，周旋折旋奉。","不然命何物，夏后氏特重。","亦有卫武公，靡乐在蒙诵。","智慧固不工，趋避矧无用。","一日所履历，一夕自甄综。","神明甘如饴，何处容隐痛。","沈沈察其几，默默课于梦。","少年谰语多，斯言粹无缝。","患难汝何物，?者为汝动。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其七","f":"五言古诗","c":["我生爱前辈，匪尽获我心。","论交少年场，岁月逝骎骎。","少年太飞扬，由哀乐不深。","礌硠听高谭，有谛难为寻。","风霜欺脆枝，金石成苦音。","前辈即背谬，厥谬亦沈沈。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其八","f":"五言古诗","c":["弱龄羡高隐，端居媚幽独。","晨诵白驹诗，相思在空谷。","稍长诵楚些，《招魂》招且读。","陈为乐之方，巫阳语何缛。","嘉遁苦太清，行乐苦太浊。","愿言移歌钟，来就伊人躅。","天涯当兰蕙，吾心当丘壑。","蹉跎复蹉跎，芳流雨寂寞。","忽忽生遐心，终朝閟金玉。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其九","f":"五言古诗","c":["一代功令开，一代人材起。","虽生云礽朝，实增祖宗美。","日开国之留，其言在青史。","何代无先君，何时无哲士。","煌煌祖宗心，斯人独称旨。","天姿若麟凤，宏加以切劘。","稽古有遥源，遵王无覂轨。","在昔与先民，三称口容止。","少壮心力殚，匪但求荣仕。","有高千载心，为本朝瑰玮。","人或玷功令，功令不任诽。","屋漏胎此心，九庙赫在咫。","天步其艰哉，光岳钟艰恃。","盲气六合来，初日照濛汜。","抱此葵藿孤，斯人拙无比。","一夫起锄之，万夫孰指使。","一夫怒用目，万夫怒用耳。","目怒活犹可，耳怒杀我矣。","去去亦何求，买山请归尔。","不先百年生，难向苍苍理。","著书落人间，高名亦难毁。","其言明且清，胡由妒神鬼。","大药可延年，名山可送死。","死生竟何憾，将毋九庙耻。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其十","f":"五言古诗","c":["兰台序九流，儒家但居一。","诸师自有真，未肯附儒术。","后代儒益尊，儒者颜益厚。","洋洋朝墅间，流亦不止九。","不知古九流，存亡今孰多。","或言儒先亡，此语又如何。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其十一","f":"五言古诗","c":["寿短苦心长，心绪每不竟。","岂徒庸庸流，赍志有贤圣。","为鬼那能续，他生渺茫更。","所以难放达，思得贤子孙。","继志与述事，大哉孝之源。","长夜集百端，蚤起无一言。","傥能心亲心，即是续亲寿。","呼儿将告之，衋然先自疚。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其十二","f":"五言古诗","c":["中年何寡欢，心绪不缥缈。","人事日龌龊，独笑时颇少。","忽忆姚归安，锡我箴铭早。","雅俗同一源，盍向源头讨。","汝自界限之，心光眼光小。","万事之波澜，文章天然好。","不见六经语，三代俗语多。","孔一以贯之，不一待如何。","实悟实证后，无道亦无魔。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其十三","f":"五言古诗","c":["晓枕心气清，奇泪忽盈把。","少年爱恻悱，芳意嫭幽雅。","黄尘澒洞中，古袌不可写。","万言摧烧之，奇气又瘖哑。","心死竟何云，结习幸渐寡。","忧患稍稍平，此心即佛者。","独有爱根在，拔之■难下。","梦中慈母来，絮絮如何舍。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其十四","f":"五言古诗","c":["危哉昔几败，万仞堕无垠。","不知有忧患，文字樊其身。","岂但恋文字，嗜好维甘辛。","出入仙侠间，奇悍无等伦。","渐渐疑百家，中无要道津。","纵使精气留，碌碌为星辰。","闻道幸不迟，多难乃维因。","空王开觉路，网尽伤心民。"]},{"t":"自春徂秋偶有所触拉杂书之漫不诠次得十五首 其十五","f":"五言古诗","c":["戒诗昔有诗，庚辰诗语繁。","第一欲言者，古来难明言。","姑将谲言之，未言声又吞。","不求鬼神谅，矧向生人道。","东云露一鳞，西云露一爪。","与其见鳞爪，何如鳞爪无。","况凡所云云，又鳞爪之余。","忏悔首文字，潜心战空虚。","今年真戒诗，才尽何伤乎。"]},{"t":"秋夜花游","f":"五言古诗","c":["海棠与江蓠，同艳异今古。","我折江蓠花，间以海棠妩。","狂呼红烛来，照见花双开。","恨不称花意，踟蹰清酒杯。","酒杯清复深，秋士多春心。","且遣秋花妒，毋令秋魄沈。","云何学年少，四座花齐笑。","踯躅取鸣琴，弹琴置当抱。","灵雨忽滂沱，仙真窗外过。","云中君至否，不敢问星娥。"]},{"t":"东陵纪役 其一","f":"五言律诗","c":["天伣徽音在，龙飞故剑亡。","两宫仪裴亹，七萃泪淋浪。","郁律川原势，低徊葆吹长。","东行三百里，何处白云乡。"]},{"t":"东陵纪役 其二","f":"五言律诗","c":["帝子华年小，初弦宝月沈。","端娴三肃礼，悯动六宫深。","徒殡飞秋雪，迎神下彩禽。","松楸依在咫，慈孝万年心。"]},{"t":"东陵纪役 其三","f":"五言律诗","c":["閤事疏朝请，君恩许看山。","日衔宿星去，神拂凤皇还。","望眼将连海，诗声欲过关。","云旗风马队，旬日梦魂间。"]},{"t":"题吴南芗东方三大图","f":"五言古诗","c":["禽父始宅奄，犹未荒大东。","周王有名祀，名山止龟蒙。","尚父赐履海，泱泱表大风。","时无神仙言，不睹金银宫。","春秋贬宋父，坐失玉与弓。","祊田富汤沐，季旅何懜懜。","秦穆作西畤，帝醉终可逢。","恒无三脊茅，遂辍登山踪。","顽哉鲁与齐，灵气不牖衷。","孤负介海岱，海深岱徒崇。","素王张三世，元始而麟终。","文成号数万，太平告成功。","其文富沧海，其旨高苍穹。","于是海岱英，尽入孔牢笼。","熙朝翠华至，九跪迎上公。","厥典盛谒林，汉后无兹隆。","惜哉有阙遗，未举金泥封。","小臣若上议，廷臣三日聋。","首谒孔林毕，继请行升中。","继请射沧海，三事碑三通。","古体日霾晦，但嗤秦汉雄。","周情与孔思，执笔思忡忡。"]},{"t":"行路易","f":"古风","c":["东山猛虎不吃人，西山猛虎吃人，南山猛虎吃人，北山猛虎不食人。","漫漫趋避何所已，玉帝不遣牖下死，一双瞳神射秋水。","袖中芳草岂不香，手中玉麈岂不长。","中妇岂不姝，座客岂不都。","江大水深多江鱼，江边何哓呶。","人不足，盱有馀，夏父以来目矍矍。","我欲食江鱼，江水涩咙喉，鱼骨亦不可以餐。","冤屈复冤屈，果然龙蛇蟠我喉舌间，使我说天九难、说地九难。","踉跄入中门，中门一步一荆棘，大药不疗膏肓顽。","鼻涕一尺何其孱，臣请逝矣逝勿还。","嘈嘈舟师，三五詈汝：汝以白昼放歌为可惜，而乃脂汝辖。","汝以黄金散尽为复来，而乃鞭其脢。","红玫瑰，青镜台，美人别汝光徘徊。","腷腷膊膊，鸡鸣狗鸣。","淅淅索索，风声雨声。","浩浩荡荡，仙都玉京。","蟠桃之花万丈明，淮南之犬彳亍行。","臣岂不如武皇阶下东方生。","乱曰：三寸舌，一枝笔，万言书，万人敌，九天九渊少颜色。","朝衣东市甘如饴，玉体须为美人惜。"]},{"t":"梦得“东海潮来月怒明”之句，醒，足成一诗 其一","f":"七言律诗","c":["昙誓天人度有情，上元旌节过双成。","西池酒罢龙娇语，东海潮来月怒明。","梵史竣编增楮寿，花神宣敕赦词精。","不知半夜归环佩，问是崆峒第几声。"]},{"t":"梦得“东海潮来月怒明”之句，醒，足成一诗 又成一诗 其二","f":"七言绝句","c":["东海潮来月上弦，崆峒抚罢静诸天。","西池一宴无消息，替管桃花五百年。"]},{"t":"邻儿半夜哭","f":"五言古诗","c":["邻儿半夜哭，或言忆前生。","前生何所忆，或者变文名。","我有一箧书，属草殊未成。","涂乙迨一纪，甘苦万千并。","百忧消中夜，何如坐经营。","剪烛蹶然起，婢笑妻复嗔。","万一明朝死，堕地泪纵横。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其一","f":"七言绝句","c":["少小无端爱令名，也无学术误苍生。","白云一笑懒如此，忽遇天风吹便行。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其二","f":"七言绝句","c":["文格渐卑庸福近，不知庸福究何如。","常州庄四能怜我，劝我狂删乙丙书。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其三","f":"七言绝句","c":["情多处处有悲欢，何必沧桑始浩叹。","昨过城西晒书地，蠹鱼无数讯平安。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其四","f":"七言绝句","c":["手种江山千树花，今年负杀武陵霞。","梦中自怯才情减，醒又缠绵感岁华。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其五","f":"七言绝句","c":["庞眉名与段公齐，一脉东原高第题。","回首外家书帙散，大儒门祚古难跻。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其六","f":"七言绝句","c":["昨日相逢刘礼部，高言大句快无加。","从君烧尽虫鱼学，甘作东京卖饼家。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其七","f":"七言绝句","c":["十年提倡受恩身，惨绿年华记忆真。","江左名场前辈在，敢将名氏厕陈人。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其八","f":"七言绝句","c":["偶赋山川行路难，浮名十载避诗坛。","贵人相讯劳相护，莫作人间清议看。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其九","f":"七言绝句","c":["万柳堂前一柳无，词流散尽散樵苏。","山东不少升平相，为溯前茅冯益都。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其十","f":"七言绝句","c":["荷叶粘天玉蝀桥，万重金碧影如潮。","功成倘赐移家住，何必湖山理故箫。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其十一","f":"七言绝句","c":["交臂神峰未一登，梦吞丹篆亦何曾。","丈夫三十愧前辈，识字游山两不能。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其十二","f":"七言绝句","c":["楼阁参差未上灯，菰芦深处有人行。","凭君且莫登高望，忽忽中原暮霭生。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其十三","f":"七言绝句","c":["东抹西涂迫半生，中年何故避声名。","才流百辈无餐饭，忽动慈悲不与争。"]},{"t":"杂诗，己卯自春徂夏，在京师作，得十四首 其十四","f":"七言绝句","c":["欲为平易近人诗，下笔清深不自持。","洗尽狂名消尽想，本无一字是吾师。"]},{"t":"题红蕙花诗册尾 其一","f":"七言绝句","c":["香满吟笺酒满卮，枫桥宾客夜灯时。","故家池馆今何许，红蕙花开空染枝。"]},{"t":"题红蕙花诗册尾 其二","f":"七言绝句","c":["读罢一时才子句，《骚》香汉艳各精神。","十年我恨生差晚，不见风流种蕙人。"]},{"t":"题红蕙花诗册尾 其三","f":"七言绝句","c":["歌板无聊舞袖凉，江南词话断人肠。","人生合种闲花草，莫遣黄金怨国香。"]},{"t":"题红蕙花诗册尾 其四","f":"七言绝句","c":["眼前谁是此花身，寂寞猩红万古春。","花有家乡侬替管，五湖添个泛舟人。"]},{"t":"张诗舲前辈游西山归索赠三首 其一","f":"七言绝句","c":["鸾吟凤叫下人寰，绝顶题名振笔还。","樵客忽传仙墨满，禁中才子昨游山。"]},{"t":"张诗舲前辈游西山归索赠三首 其二","f":"七言绝句","c":["去年扈从东巡守，玉佩琼琚大放辞。","等是才华不巉削，愿携康乐诵君诗。"]},{"t":"张诗舲前辈游西山归索赠三首 其三","f":"七言绝句","c":["畿辅千山互长雄，太行一臂怒趋东。","祝君腰脚长如意，吟遍蜿蜒北干龙。"]},{"t":"驿鼓三首 其一","f":"七言律诗","c":["河灯驿鼓满天霜，小梦温黁乱客肠。","夜久罗帱梅弄影，春寒银铫药生香。","慈闱病减书频寄，稚子功闲日渐长。","欲取离愁暂抛却，奈君针线在衣裳。"]},{"t":"驿鼓三首 其二","f":"七言律诗","c":["钗满高楼灯满城，风花未免态纵横。","长途借此销英气，侧调安能犯正声。","绿鬓人嗤愁太早，黄金客怒散无名。","吾生万事劳心意，嫁得狂奴孽已成。"]},{"t":"驿鼓三首 其三","f":"七言律诗","c":["书来恳款见君贤，我欲收狂渐向禅。","早被家常磨慧骨，莫因心病损华年。","花看天上祈庸福，月堕怀中听幻缘。","一卷金经香一炷，忏君自忏法无边。"]},{"t":"发洞庭，舟中怀钮非石树玉、叶青原昶","f":"五言律诗","c":["西山春昼别，两袖落梅风。","不见小龙渚，尚闻隔渚钟。","樽前荇叶白，舵尾茶华红。","仙境杳然杳，酸吟雨一篷。"]},{"t":"此游 其一","f":"七言绝句","c":["此游好补前游罅，挥手云声浩不闻。","两度山灵濡笔记，钱塘君访洞庭君。"]},{"t":"此游 其二","f":"五言律诗","c":["舟到西山岸，寻幽迤逦斜。","居然六七里，无境不烟霞。","遂发石公寺，定过神女家。","云和风静里，已度万梅花。"]},{"t":"此游 其三","f":"五言律诗","c":["风意中流引，香烟在屿迟。","悠扬闻杜若，仿佛邀蛾眉。","白日憺明镜，春空飘彩旗。","湖东一回首，万古长相思。"]},{"t":"过扬州","f":"七言绝句","c":["春灯如雪浸兰舟，不载江南半点愁。","谁信寻春此狂客，一茶一偈过扬州。"]},{"t":"观心","f":"五言律诗","c":["结习真难尽，观心屏见闻。","烧香僧出定，哗梦鬼论文。","幽绪不可食，新诗如乱云。","鲁阳戈纵挽，万虑亦纷纷。"]},{"t":"又忏心一首","f":"七言律诗","c":["佛言劫火遇皆销，何物千年怒若潮。","经济文章磨白昼，幽光狂慧复中宵。","来何汹涌须挥剑，去尚缠绵可付箫。","心药心灵总心病，寓言决欲就灯烧。"]},{"t":"庚辰春日重过门楼胡衕故宅","f":"五言古诗","c":["城西郎官屯，多官阅一宅。","家公昔为郎，有此湫隘室。","朝阳与夕阳，屋角红不积。","春雨复秋雨，双扉故钉齿。","无形不知老，有质乃易蚀。","往事思之悔，至理悟独立。","中有故我魂，三呼如欲出。"]},{"t":"因忆两首 其一","f":"五言律诗","c":["因忆横街宅，槐花五丈青。","文章酸辣早，《知觉》鬼神灵。","大挠支干始，中年记忆荧。","东墙凉月下，何客又横经。"]},{"t":"因忆两首 其二","f":"五言律诗","c":["因忆斜街宅，情苗茁一丝。","银缸吟小别，书本画相思。","亦具看花眼，难忘授《选》时。","泥牛入沧海，执笔向空追。"]},{"t":"客春，住京师之丞相胡衕，有丞相胡衕春梦诗二十绝句。春又深矣，因烧此作，而奠以一绝句","f":"七言绝句","c":["春梦撩天笔一枝，梦中伤骨醒难支。","今年烧梦先烧笔，检点青天白昼诗。"]},{"t":"春晚送客","f":"七言绝句","c":["潞水滔滔南向流，家书重叠附征邮。","行人临发长亭晚，更折梨花寄暮愁。"]},{"t":"琴歌","f":"古风","c":["之美一人，乐亦过人，哀亦过人。","月生于堂，匪月之精光，睇视之光。","美人沈沈，山川满心。","落月逝矣，如之何勿思矣。","美人沈沈，山川满心。","吁嗟幽离，无人可思。"]},{"t":"偶感","f":"七言绝句","c":["昆山寂寂弇山寒，玉佩琼琚过眼看。","一事飞腾羡前辈，升平时世读书官。"]},{"t":"赵晋斋魏、顾千里广圻、钮非石树玉、吴南芗文徵、江铁君沅，同集虎邱秋宴作","f":"七言律诗","c":["尽道相逢日苦短，山南山北秋方腴。","儿童敢笑诗名贱，元气终须老辈扶。","四海典彝既旁达，两山金石谁先储。","影形各各照秋水，渣滓全空一世无。"]},{"t":"题虎跑寺","f":"七言绝句","c":["南山跸路丙申开，庚子诗碑锁绿苔。","曾是纯皇亲幸地，野僧还盼大行来。"]},{"t":"杭州龙井寺","f":"七言绝句","c":["红泥亭倒客来稀，钟磬沉沉出翠微。","无分安禅翻破戒，盗他常住一花归。"]},{"t":"怀沈五锡东、庄四绶甲","f":"七言绝句","c":["白日西倾共九州，东南词客愀然愁。","沈生飘荡庄生废，笑比陈王丧应、刘。"]},{"t":"呜呜硻硻","f":"古风","c":["黄犊怒求乳，朴诚心无猜。","犊也尔何知，既壮恃其孩。","古之子弄父兵者，喋血市上宁非哀。","亦有小心人，天命终难夺。","授命何其恭，履霜何其洁。","孝子忠臣一传成，千秋君父名先裂。","不然冥冥鸿，无家在中路。","恝哉心无瑕，千古孤飞去。","呜呜复呜呜，古人谁智谁当愚。","雰复雰，智亦未足重，愚亦未可轻。","鄙夫较量愚智间，何如一意求精诚。","仁者不訹愚痴之万死，勇者不贪智慧之一生。","寄言后世艰难子，白日青天奋壁行。"]},{"t":"幽人","f":"五言律诗","c":["幽人媚清晓，落月澹林光。","欲采蘅兰去，春空风露香。","阿谁叫横玉，惊起绿烟床。","亦有梅花梦，颓鬟待太阳。"]},{"t":"寒夜读归佩珊夫人赠诗，有“删除荩箧闲诗料，湔洗春衫旧泪痕”之语，怃然和之","f":"七言律诗","c":["风情减后闭闲门，襟尚馀香袖尚温。","魔女不知侵戒体，天花容易陨灵根。","蘼芜径老春无缝，薏苡谗成泪有痕。","多谢诗仙频问讯，中年百事畏重论。"]},{"t":"昨夜二首 其一","f":"七言绝句","c":["昨夜江潮平未平，篷窗有客感三生。","药炉卧听浑如沸，不似墙东钗钏声。"]},{"t":"昨夜二首 其二","f":"七言绝句","c":["种花都是种愁根，没个花枝又断魂。","新学甚深微妙法，看花看影不留痕。"]},{"t":"紫云回三叠 其一","f":"七言绝句","c":["安香舞罢杜兰催，水瑟冰敖各费才。","别有伤心听不得，珠帘一曲《紫云回》。"]},{"t":"紫云回三叠 其二","f":"七言绝句","c":["神仙眷属几生修，小妹承恩阿姊愁。","宫扇已遮帘已下，痴心还伫殿东头。"]},{"t":"紫云回三叠 其三","f":"七言绝句","c":["上清丹箓姓名讹，好梦留仙夜夜多。","争似芳魂惊觉早，天鸡不曙渡银河。"]},{"t":"咏史二首 其二","f":"七言律诗","c":["一样苍生系庙廊，南风愁绝北风狂。","羽书颠倒司农印，幕府纵横急就章。","奇计定无宾客献，冤氛可顾子孙殃。","何年秘客搜诗史，输与山东客话长。"]},{"t":"赠伯恬","f":"七言绝句","c":["毗陵十客献清文，五百狻猊屡送君。","从此周郎闭门卧，落花三月断知闻。"]},{"t":"广陵舟中为伯恬书扇","f":"七言绝句","c":["红豆生苗春水波，齐梁人老奈愁何。","逢君只合千场醉，莫恨今生去日多。"]},{"t":"读公孙弘传","f":"七言绝句","c":["三策天人礼数殊，公孙相业果何如。","可怜秋雨文园客，身是赀郎有谏书。"]},{"t":"马","f":"七言绝句","c":["八极曾陪穆满游，白云往事使人愁。","最怜汗血名成后，老踞残刍立仗头。"]},{"t":"吴市得题名录一册，乃明崇祯戊辰科物也，题其尾一律","f":"七言律诗","c":["天心将改礼闱徵，养士犹传十四陵。","板荡人材科目重，蓁芜文体史家凭。","朱衣点过无光气，淡墨堆中有废兴。","资格未高沧海换，半为义士半为僧。"]},{"t":"才尽","f":"五言律诗","c":["才尽不吟诗，非关象喙危。","青山有隐处，白日无还期。","病骨时流恕，春愁古佛知。","观河吾见在，莫畏镜中丝。"]},{"t":"铁君惠书，有“玉想琼思”之语，衍成一诗答之","f":"七言绝句","c":["我昨青鸾背上行，美人规劝听分明。","不须文字传言语，玉想琼思过一生。"]},{"t":"戒诗五首 其一","f":"五言古诗","c":["蚤年撄心疾，诗境无人知。","幽想杂奇悟，灵香何郁伊。","忽然适康庄，吟此天日光。","五岳走骄鬼，万马朝龙王。","不遇善知识，安知因地孽。","戒诗当有诗，如偈亦如喝。"]},{"t":"戒诗五首 其二","f":"五言律诗","c":["百脏发酸泪，夜涌如原泉。","此泪何所从，万一诗祟焉。","今誓空尔心，心灭泪亦灭。","有未灭者存，何用更留迹。"]},{"t":"戒诗五首 其三","f":"五言律诗","c":["行年二十九，电光岂遽收。","观河生百喟，何如泛虚舟。","当喜我必喜，当忧我辄忧。","尽此一报形，世法随沈浮。"]},{"t":"戒诗五首 其四","f":"五言律诗","c":["天龙为我喜，波旬为我愁。","波旬尔勿愁，咒汝械汝头。","律居三藏一，天龙所护持。","我今戒为诗，戒律亦如之。"]},{"t":"戒诗五首 其五","f":"五言律诗","c":["堕落有时有，三涂报则否。","舌广而音宏，天女侍前后。","遍召忠孝魂，座下赐卮酒。","屈曲缭戾情，千义听吾剖。"]},{"t":"菩萨蛮","f":"古风","c":["文廊匼匝屏风曲。","轻寒恻恻侵帘箔。","秋思正沈吟。","秋阴几许深。","无言垂翠袖。","粉蝶窥人瘦。","蝶也不禁秋。","凉花相对愁。"]},{"t":"梦芙蓉 本意","f":"古风","c":["背灯敧凤枕。","见一珠秋弄，水裙风鬓。","露华无力，飞下珊珊影。","又微芒不定，月坠金波孤迥。","小立空塘，怨红衣半卸，消受夜凉紧。","脉脉鸳鸯暝正稳。","乍莲房、粉坠惊初醒。","香重烟轻，愁绝共幽映。","五更魂魄冷。","吟断锦云休讯。","捐佩疑寒，更凌波恐湿，塘外晓风阵。"]},{"t":"卜算子 頠独立士女","f":"古风","c":["拜起月初三，月比眉儿瘦。","不遣红灯照画廊，缥缈临风袖。","庭院似清湘，人是湘灵否。","谁写长天秋思图，熨得栏干透。"]},{"t":"点绛唇","f":"古风","c":["日落花梢，恹恹春倦何时省。","纱窗又暝。","黄月濛濛影。","没个商量，除是和愁等。","罗衣冷。","香阶红阵。","燕子归期定。"]},{"t":"虞美人","f":"古风","c":["纱窗暝色低迷绿。","犹未传银烛。","春寒瑟瑟晚来添。","玉钏微闻应是换吴棉。","金炉香篆愔愔堕。","新月窥人坐。","湘帘放下悄含颦。","生怕梨花和月射啼痕。"]},{"t":"洞仙歌","f":"古风","c":["一梳春月，淡溶溶欲上，鸾尾云晴碧天扫。","正文窗四扇，缥缈华空，晶艳艳，玉女明灯一笑。","几番携手处，昙誓天边，寒绿深深帐纱悄。","亲手采琼芝，著玉盘中，添香水、养花还小。","见说道、仙家梦都无，便梦也如烟，晓凉欺觉。"]},{"t":"醉太平","f":"古风","c":["长吟短吟。","恩深怨深。","天边一曲瑶琴。","是鸾心凤心。","香沈漏沈。","魂寻梦寻。","玉阶良夜愔愔。","有花阴月阴。"]},{"t":"清平乐","f":"古风","c":["垂杨近远。","玉鞚行来缓。","三里春风韦曲岸。","目断那人庭院。","驻鞭独自思惟。","撩人历乱花飞。","日暮春心怊怅，可能纫佩同归。"]},{"t":"太常引","f":"古风","c":["一身云影堕人间。","休认彩鸾看。","花叶寄应难。","又何况、春痕袖斑。","似他身世，似他心性，无恨到眉弯。","月子下屏山。","算窥见、瑶池梦还。"]},{"t":"端正好","f":"古风","c":["数年华闲中黯黯。","记不起、谁思谁怨。","金炉香袅昼沈沈，并叠作，闲愁片。","月明花满天如愿。","也终有、酒阑灯散。","不如被冷更香销，独自去，思千遍。"]},{"t":"霓裳中序第一 霓裳羽衣之曲今不传，戏补之","f":"古风","c":["当筵问古月。","谁向其间起宫阙。","风马云车历历。","见桂葆、乍迎娇如雪。","遥空闻说。","说夜来、天袂凉绝。","惊鸿起，素衣二八，舞罢老蟾泣。","飘忽。","长风吹急。","竟天上、人间了隔。","仙声一半记得。","汉武秦皇，有路难觅。","开元庆佳节。","算合乐、图中应识。","尊前祝，千秋万岁，不须有离别。"]},{"t":"长相思二首 其一","f":"古风","c":["仙参差。","佩参差。","数罢鸾期又凤期。","彩云西北飞。","箫一枝。","笛一枝。","吹得春空月堕时。","有中人未归。"]},{"t":"长相思二首 其二","f":"古风","c":["住西楼。","话西楼。","好梦如云不自由。","唤人饧倦眸。","忆从头。","诉从头。","银汉茫茫入夜流。","人间无尽愁。"]},{"t":"天仙子 自赋所藏叶小鸾眉纹诗砚","f":"古风","c":["天仙偶厌住琼楼。","乞得人间一度游。","被谁传下小银钩。","烟淡淡，月柔柔。","伴我熏香伴我修。"]},{"t":"瑶华 挠双成画像","f":"古风","c":["云英嫁了，弄玉归来，向翠楼琼户。","虚无万叠，试问取、金阙西厢何处。","容华绝代，是王母、前头人数。","看紫衣、仙佩非耶，汉殿夜凉归去。","低鬟小按霓裳，唱月底仙声，记否亲遇。","霞宫侍宴，浑忘了、听水听风前度。","天青海碧，也只合、其中小住。","笑人间、儿女聪明，倒写成双名字。"]},{"t":"浪淘沙 饼梦","f":"古风","c":["好梦最难留。","吹过仙洲。","寻思依样到心头。","去也无踪寻也惯，一桁红楼。","中有话绸缪。","灯火帘钩。","是仙是幻是温柔。","独自凄凉还自遗，自制离愁。"]},{"t":"如梦令","f":"古风","c":["本是花宫么凤。","降作人间情种。","不愿住人间，分付药炉烟送。","谁共。","谁共。","三十六天秋梦。"]},{"t":"高阳台","f":"古风","c":["嚼曲含香，吹笙聘月，华年心绪愔愔。","十二重帘，重重阁住春阴。","花魂蝶梦飞难度，倩何人、料理幽襟。","问春人，知否园亭，啼遍流莺。","生愁一点朝云散，把青梅细数，红豆闲吟。","尚怯馀寒，争教负了香衾。","痴鬟不放熏篝稳，坠猩红、半幅吴绫。","启湘屏，多病心情，忘系花铃。"]},{"t":"喝火令","f":"古风","c":["欲赋仙模样，空愁彩笔雕。","藕丝衫子郁金翘。","立到水芝花上，罗袜未香消。","端正当窗户，停匀亸步摇。","断无幽意上眉梢。","只恐凝妆，只恐背人娇。","只恐梦回香泪，揩上枕头绡。"]},{"t":"木兰花慢","f":"古风","c":["问人天何事，最飘渺，最销沈。","算第一难言，断无人觉，且自幽寻。","香兰一枝凭瘦，问香兰、何苦伴清吟。","消受工愁滋味，天长地久愔愔。","兰襟。","一丸凉月，堕似他心。","有梦诉依依，香传袅袅，眉锁深深。","故人碧空有约，待归来、天上理天琴。","无奈游仙觉后，碧云垂到而今。"]},{"t":"菩萨蛮","f":"古风","c":["行云欲度帘旌去。","啼花恨草无重数。","吟淡口脂痕。","秋心自觉温。","秋怀珠与玉。","写上罗笺薄。","暮暮与朝朝。","工愁要福销。"]},{"t":"惜分钗","f":"古风","c":["金铺晓。","搴帏早。","嫩寒漠漠欺人觉。","雾沈香。","额微黄。","报道寒梅，也学晨妆。","双。","双。","明窗掩。","重帘软。","炉香自炙红丝砚。","点银钩。","记清愁。","待把琴心，寄与西洲。","休。","休。"]},{"t":"如梦令","f":"古风","c":["紫点红愁无绪。","日暮春归甚处。","春更不回头，撇下一天浓絮。","春住。","春住。","黦了人家庭宇。"]},{"t":"金明池","f":"古风","c":["按拍填词，拈箫谱字，白日销磨无绪。","春梦断、拈天香草，试怅望、美人何处。","中馀酲、才要醒时，却又被艳想、迷漫遮住。","早燕子匆忙，杨花零乱，好煞年光将去。","料理相逢今又误。","问除却相思，怎生言语。","笺闲恨、丝烦絮乱，制密意、绿愁红妒。","甚天工、作就慵时，有万种忪惺，十分凝伫。","便拚不怀人，从今决绝，如此情悰消否。"]},{"t":"一剪梅","f":"古风","c":["一丸微月破黄昏。","卷定帘痕。","划定炉痕。","春归谁与试温存。","春瘦三分。","人瘦三分。","柳花桃叶正纷纷。","掩了重门。","阁了芳樽。","安排怊怅倚罗屏。","红字消魂。","香字招魂。"]},{"t":"青玉案","f":"古风","c":["韶光不怨匆匆去。","只怊怅，年华误。","目断游丝情一缕。","断桥流水，夕阳飞絮，可是春归路。","楼头尽日还凝伫。","欲诉闲愁向谁诉。","蕙渚花飞天又暮。","醒时如醉，醉时如梦，梦也何曾作。"]},{"t":"莺啼序 用宋人韵","f":"古风","c":["残年半销金兽，启朱帘琐户。","悄凝盼、十里蘅皋，多少心期伤暮。","梦回后、半霎凭栏，春烟阁断天涯树。","仗莺魂有力，唤起一天浓絮。","昨日闲愁，今朝暗恨，似濛云惹雾。","拈彩笔、亲制红词，有人怜赏心素。","正沉沉、春深似海，低徊年华金缕。","作人间、病凤啼鸾，原输鸥鹭。","胭脂含怨，锦瑟生愁，怅春似逆旅。","枉二十四番寒暖，次第催完，变了漫空，扑人花雨。","钗寒佩瘦，红敧绛病，惺惺胡蝶谁家宿，况连天、香草崇兰渡。","予怀渺渺，灵修尚隔中央，只恐弃我如土。","凌波袜懒，绣线裙松，换吴棉白苧。","为一种、心情无奈，断送韶颜，憔悴而今，劝君休舞。","浑都不管，愁侬怨汝。","灵犀一寸明见，更何须、弄入瑶琴柱。","纱窗日落无人，独倚黄昏，有谁省否。"]},{"t":"菩萨蛮","f":"古风","c":["吴棉一幅单鸳被。","沈沈和雾和香睡。","花气湿银屏。","红窗斜月明。","玉阑干畔路。","晓梦无寻处。","梦醒转沈吟。","花寒恐不禁。"]},{"t":"临江仙二首 其一","f":"古风","c":["一角红窗低嵌月，矮屏山蹙罗纹。","梨花情性怕黄昏。","泪怜银蜡浅，心比玉炉温。","底事雏鬘憨不醒，冬冬虬箭宵分。","起来亲手放帘痕。","春空凉似水，西北有娇云。"]},{"t":"临江仙二首 其二","f":"古风","c":["酒渴思茶交午饭，沈烟闲拨钗梁。","小梅花盒教添香。","填词浑已懒，何况脱衣裳。","才把梦儿牢捉住，无端又著思量。","十分情愿是回肠。","欲抛抛不得，敧枕数鸳鸯。"]},{"t":"浣溪沙二首 其一","f":"七言古诗","c":["香雾无情作薄寒。","银灯吹处气如兰。","凭肩人爱夜阑珊。","花语绿窗凉月听，云敧文枕画鸾看。","钏声微戛梦儿难。"]},{"t":"浣溪沙二首 其二","f":"七言古诗","c":["凤胫灯青香篆寒。","寻思脉脉未成眠。","敧鬟沈坐溜犀钿。","一帧梅花红似酒，半庭春月暖于烟，红阑干外夜阑珊。"]},{"t":"梦行云","f":"古风","c":["晓帏怯春冷。","重帘下，眠未醒。","休翻翠被，恐教人惊省。","一枝艳艳文窗外，梨花凉弄影。","唾华襟上，啼红枕上，悲欢事，留浅印。","娇柔无语，倩人探心性。","十分打叠情怀起，怕花愁月病。"]},{"t":"洞仙歌","f":"古风","c":["轻寒漠漠，又杏花天气。","卸了吴棉薄纨腻。","把花魂细绾，月梦低敲，闲谱得、十叠新词堪记。","番番圆艳约，春事迷人，絮影风光太消碎。","小病不胜春，懒想秾愁，拚略受、情多风味。","又银烛、传来劝笺愁，看比玉能红，比箫能脆。"]},{"t":"导引曲二首 其一","f":"古风","c":["无情绪，无情绪，寂寞掩重门。","银蜡心多才有泪，宝香字断更无痕。","梨花浸黄昏。"]},{"t":"导引曲二首 其二","f":"古风","c":["空相忆，空相忆，庭院四更天。","怊怅绿梅花下路，半襟斜月不知寒。","凤屧过阑干。"]},{"t":"玉联环影","f":"古风","c":["胧月魂傍花阴立。","红泪留痕，一片花枝湿。","袖儿寒。","佩儿寒。","依旧五更风急，梦吹残。"]},{"t":"南歌子","f":"古风","c":["香雾漫空湿，珠帘窣地横。","云围月拥见卿卿。","受尽轻怜痛惜不分明。","红泪弹前恨，心香警旧盟。","瑶华密帐絮三生，怊怅五更风急断魂惊。"]},{"t":"桂殿秋二首 其一","f":"古风","c":["明月外，净红尘。","蓬莱幽窅四无邻。","九霄一派银河水，流过红墙不见人。"]},{"t":"桂殿秋二首 其二","f":"古风","c":["惊觉后，月华浓。","天风已度五更钟。","此生欲问光明殿，知隔朱扃几万重。"]},{"t":"忆瑶姬","f":"古风","c":["唳鹤吟鸾，悄千门万户，夜静尘寰。","玉京宫殿杳，怅九霄仙佩，不下云軿。","今年小谪，知自何年。","消尽炼琼颜。","料素娥、今夕无人问，裙袂生寒。","定万古、长对晶盘。","敛庄严宝相，独坐婵媛。","幽怀知有恨，恨玉笙吹彻，彻骨难眠。","双成问讯，青女凭肩。","瑶华筵宴罢，长风起，吹堕离愁到世间。"]},{"t":"梦玉人引","f":"古风","c":["一箫吹。","琼栏月暖，锦云飞。","十丈银河，挽来注向灵扉。","月殿霞窗，动春空、仙籁参差。","报道双成，乍搴了罗帏。","陡然闻得，青凤下西池。","奏记帘前，佩环听处依稀。","不是人间话，何缘世上知。","梦回处，摘春星、满把累累。"]},{"t":"意难忘","f":"古风","c":["凉月姗姗。","伴兰心玉性，试语还难。","秋花分小影，秀句写冰纨。","眉意浅，佩声残。","有珍重千般。","略逗伊，隐花裙上，竹叶斑斑。","知音何苦轻瞒。","者温存隐秀，慧思华年。","明明通尔汝，瑟瑟数悲欢。","携手际，试颦间。","是意暖神寒。","玉漏沈，芙蓉睡也，重靠栏干。"]},{"t":"丑奴儿令","f":"古风","c":["鸾笺偷写伊名字，琴语依稀。","筝语依稀。","花影无媒忽进帏。","兰因絮果从头问，吟也凄迷。","掐也凄迷。","梦向楼心灯火归。"]},{"t":"凤栖梧","f":"古风","c":["谁边庭院谁边宅。","往事谁边，空际层层叠。","坐暖一方屏底月。","背人蜡影幢幢灭。","万种温黁何用觅。","枕上逃禅，遣却心头忆。","禅战愁心无气力。","自家料理回肠直。"]},{"t":"台城路 送姚怡云之江南","f":"古风","c":["平生未信江南好，输君者番归去。","明月扬州，古来英丽，端合仙才人在。","俊游目许。","有载酒词场，吹箫仙侣。","艳想秾愁，一齐翻入四红谱。","西风吟绪正苦。","又牵情冶柳，离恨千缕。","瘦砚敲霜，古笺啼月，真个销凝无主。","相思怨汝。","教独自凭楼，冷吟谁语。","一掬芙蓉，送君肠断句。"]},{"t":"鹊桥仙","f":"古风","c":["飘零也定，清狂也定，莫是前生计左。","才人老去例逃禅，问割到、慈恩真个。","吟诗也要，从军也要，何处宗风香火。","少年三五等闲看，算谁更、惊心似我。"]},{"t":"浪淘沙 有寄","f":"古风","c":["别梦醒天涯。","怊怅年华。","怀人无奈碧云遮。","我自低迷思锦瑟，谁怨琵琶。","小字记休差。","年经些些。","苏州花月是儿家。","紫杜红兰闲掐遍，何处蘋花。"]},{"t":"水调歌头 寄徐二义尊大梁","f":"古风","c":["去日一以驶，来日故应难。","故人天末不见，使我思华年。","结客五陵英少，脱手黄金一笑，霹雳应弓弦。","意气渺非昔，行役亦云艰。","湖海事，感尘梦，变朱颜。","空留一剑知己，夜夜铁花寒。","更说风流小宋，凄绝白杨荒草，谁哭墓门田。","游侣半生死，想见涕潺湲。"]},{"t":"水调歌头","f":"古风","c":["风雨飒然至，竟日作清寒。","我思芳草不见，忽忽感年华。","忆昔追随日久，正把心魂相守，灯火四更天。","高唱夜乌起，当作古人看。","一枝榻，一炉茗，宛当前。","几声草草休送，万古遂茫然。","仙字蟫饥不食，故纸蝇钻不出，陈迹太辛酸。","一掬大招泪，洒向暮云间。"]},{"t":"瑶台第一层","f":"古风","c":["无分同生偏共死，天长恨较长。","风灾不到，月明难晓，昙誓天旁。","偶然沦谪处，感俊语小玉聪狂。","人间世，便居然愿作，长命鸳鸯。","幽香。","兰言半枕，欢期抵过八千场。","今生已矣，玉钗鬟卸，翠钏肌凉。","赖红巾入梦，梦里说、别有仙乡。","渺何方。","向琼楼翠宇，万古携将。"]},{"t":"行香子 匠中书怀与汪宜伯","f":"古风","c":["跨上征鞍。","红豆抛残，有何人、来问春寒。","昨宵梦里，犹在长安。","在凤城西，垂杨畔，落花间。","红楼隔雾，珠帘卷月，负欢场、词笔阑珊。","别来几日，且劝加餐。","恐万言书，千金剑，一身难。"]},{"t":"醉太平 匠中作","f":"古风","c":["鞍停辔停。","云行树行。","东风昨夜吹魂。","过青山万痕。","春浓梦沈。","愁多酒醒。","一天飞絮愔愔。","搅离怀碎生。"]},{"t":"唐多令 匠中书怀","f":"古风","c":["二十五长亭。","垂杨照眼青。","付春风、短梦零星。","斜倚雕鞍无气力，浑不似，俊游人。","春意太憨生。","春愁唤不醒。","负华年、谁更怜卿。","惟有填词情思好，无恙也，此花身。"]},{"t":"浪淘沙 舟中夜起","f":"古风","c":["幽梦四更醒。","欸乃声停。","吴天月落半江阴。","蓦地横吹三孔笛，聘取湘灵。","螺髻锁娉婷。","烟雾青青。","看他潮长又潮平。","香草美人吟未了，防有蛟听。"]},{"t":"菩萨蛮 效蕃锦集","f":"古风","c":["娇鬟堆枕钗横凤。","青春酒压杨花梦。","翠被夜徒熏。","娇郎痴若云。","波痕空映袜。","艳净如笼月。","明月上春期。","轻红擘荔枝。"]},{"t":"蝶恋花","f":"古风","c":["酒压春愁春卷絮。","燕子归来，苦说年华误。","半晌怀人搔首伫。","落梅风急闲庭暮。","辛苦痴怀何用诉。","曲曲香痕，曲到无凭据。","安顿惜花心事处。","谢他昨夜风和雨。"]},{"t":"水龙吟 頠家绣山《听琴听箫图》","f":"古风","c":["红楼一角沈沈，那厢灯火秋娘院。","露寒花重，愁多指涩，酒醒人远。","蓦听离鸾，旋来泣凤，累人猜遍。","有相思两字，呼之欲出，秋意裂，冰纹断。","两下衷情低按。","者沈吟、偿他凄怨。","分明不是，山重水叠，几痕纱幔。","六曲春星，二分明月，可怜齐转。","把芳心整起，兜衾傍枕，倘能寻见。"]},{"t":"高阳台","f":"古风","c":["南国伤谗，西洲怨别，泪痕淹透重衾。","一笛飞来，关山何处秋声。","秋花绕帐瞢腾卧，醒来时、芳讯微闻。","费猜寻，乍道向兰奴，气息氛氲。","多愁公子新来瘦，也何曾狂醉，绝不闲吟。","璧月三圆，江南消息沈沈。","魂消心死都无法，有何人、来慰登临。","劝西风，将就些些，莫便秋深。"]},{"t":"鹊桥仙","f":"古风","c":["文窗一碧，萧萧相倚，静袅茶烟一炷。","箨龙昨夜叫秋空，似怨道、天寒如许。","安排疏密，商量肥瘦，自斸苔痕辛苦。","从今翠袖不孤清，特著个、红妆伴汝。"]},{"t":"金缕曲 蠠祗敩罨蝞小像题词","f":"古风","c":["老矣东阳沈。","算平生、徵歌说剑，十分疏俊。","太华秋高攀云上，百首淋浪诗兴。","有多少、唐愁汉恨。","忽地须弥藏芥里，取一痕、瘦石摩挲认。","颠岂敢，癖差近。","伊余顽质君休问。","笑年来、光芒万丈，被他磨尽。","愧煞平原佳公子，骏马名姝投赠。","只东抹、西涂还肯。","两载云萍交谊在，更十行、斜墨匆匆印。","他日展，寄芳讯。"]},{"t":"摸鱼儿 够亥六月留别新安作","f":"古风","c":["者溟濛、江云岳雨，是谁招我来住。","空桑三宿犹生恋，何况三年吟绪。","来又去。","可题遍、莲花六六峰头路。","幽怀更苦。","问官阁梅花，谁家公子，来咏断魂句。","眠餐好，多谢濒行嘱咐。","吾家有妹工赋。","相思咫尺江关耳，切莫悲欢自诉。","君信否。","只我已、年来习气消花絮。","词章不作。","倘绝业成时，年华尚早，听我壮哉语。"]},{"t":"卖花声 舟过白门有纪","f":"古风","c":["帆饱秣陵烟。","回首依然。","红墙西去小长干。","好个当垆人十五，春满垆边。","如此六朝山。","消此鸦鬟。","雨花云叶太阑珊。","百里江声流梦去，重到何年。"]},{"t":"百字令 苏州晤归夫人佩珊索题其集","f":"古风","c":["扬帆十日，正天风吹绿，江南万树。","遥望灵岩山下气，识有仙才人住。","一代词清，十年心折，闺阁无前古。","兰霏玉映，风神消我尘土。","人生才命相妨，男儿女士，历历俱堪数。","眼底云萍才合处，又道伤心羁旅。","南国评花，西湖吊旧，东海趋庭去。","红妆白也，逢人夸说亲睹。"]},{"t":"摸鱼儿","f":"古风","c":["数东南、千岩万壑，君家第一奇秀。","云消缥缈峰峦下，闲锁春寒十亩。","春乍漏。","有樵笛来时，报道燕支透。","花肥雪瘦。","向寂寂空青，潺潺古碧，铁干夜龙吼。","幽人喜，扶杖欣然而走。","酒神今日完否。","山妻妆罢浑无事，供佛瓶中空久。","枝在手。","好赠是、芦帘纸阁归来守。","寒图写就。","看画稿奴偷，词腔婢倚，清梦不僝僽。"]},{"t":"减兰","f":"古风","c":["人天无据。","被侬留得香魂住。","如梦如烟。","枝上花开又十年。","十年千里。","风痕雨点斓斑里。","莫怪怜他。","身世依然是落花。"]},{"t":"长相思","f":"古风","c":["海棠丝。","杨柳丝。","小别风丝雨也丝。","春愁乱几丝。","早寒时。","暮寒时。","江上春潮平岸时。","谢庭书到时。"]},{"t":"满江红 代家大人题苏刑部寒山奉使卷子","f":"古风","c":["草白云黄，壁立起，塞山青陡。","谁貌取、书生骨相，健儿身手。","地拱龙兴犄角壮，时清鹭斥消烽久。","仗征人，笛里叫春回，歌杨柳。","飞鸿去，泥踪旧。","奇文在，佳儿守。","问摩挲三五，龙泉在否。","我亦高秋三扈跸，穹庐落日鞭丝骤。","对西风，挂起北征图，沾双袖。"]},{"t":"台城路","f":"古风","c":["城西一角临官柳，阴阴画楼低护。","冶叶倡条，年年见惯，露里风中无数。","谁家怨女。","有一种工愁，天然眉妩。","红烛欢场，惺忪敛袖正无语。","相逢纵教迟暮。","者春潮别馆，牢记迎汝。","我亦频年，弹琴说剑，憔悴江东风雨。","烦卿低诉。","怕女伴回眸，晓人心绪。","归去啼痕，夜灯瞧见否。"]},{"t":"百字令 锠腢大琴南","f":"古风","c":["深情似海，问相逢初度，是何年纪。","依约而今还记取，不是前生夙世。","放学花前，题诗石上，春水园亭里。","逢君一笑，人间无此欢喜。","无奈苍狗看云，红羊数劫，惘惘休提起。","客气渐多真气少，汩没心灵何已。","千古声名，百年担负，事事违初意。","心头阁住，儿时那种情味。"]},{"t":"金缕曲 怠亍生","f":"古风","c":["海上云萍遇。","笑频年、开樽说剑，登楼选赋。","十万狂花如梦寐，梦里花还如雾。","问醒眼、看时何许。","侬已独醒醒不惯，悔黄金、何不教歌舞。","明月外，思清苦。","奇才未必天俱妒。","只君家、通眉长爪，偶然仙去。","花月湖山骄冶甚，一种三生谁付。","只片语、告君休怒。","收拾狂名须趁早，鬓星星、渐近中年路。","容傍我，佛灯住。"]},{"t":"虞美人","f":"古风","c":["江湖听雨归来客。","手剪吴淞碧。","笛声叫起倦魂时。","飞过濛濛香雪一千枝。","少年多少熏兰麝。","金凤钗梁挂。","年来我但写莲经。","要伴荒庵一粟夜灯青。"]},{"t":"金缕曲 砠酉秋出都述怀有赋","f":"古风","c":["我又南行矣。","笑今年、鸾飘凤泊，情怀何似。","纵使文章惊海内，纸上苍生而已。","似春水、干卿何事。","暮雨忽来鸿雁杳，莽关山、一派秋声里。","催客去，去如水。","华年心绪从头理。","也何聊、看潮走马，广陵吴市。","愿得黄金三百万，交尽美人名士。","更结尽、燕邯侠子。","来岁长安春事早，劝杏花、断莫相思死。","木叶怨，罢论起。"]},{"t":"湘月 戌春泛舟西湖赋此","f":"古风","c":["湖云如梦，记前年此地，垂杨系马。","一抹春山螺子黛，对我轻颦姚冶。","苏小魂香，钱王气短，俊笔连朝写。","乡邦如此，几人名姓传者。","平生沈俊如侬，前贤倘作，有臂和谁把。","问取山灵浑不语，且自徘徊其下。","幽草黏天，绿荫送客，冉冉将初夏。","流光容易，暂时著意潇洒。"]},{"t":"水调歌头","f":"古风","c":["落日万艘下，气象一何多。","何人轻掷纱帽，帆影掠天过。","鄃上通侯如彼，江左夷吾若此，不奈怒鲸何。","挥手谢公等，径欲卧烟萝。","当局者，问何似，此高歌。","著书传满宾客，馀事貌渔蓑。","贱子平生出处，虽则闲鸥野鹭，十五度黄河。","面皱怕窥景，狂论亦消磨。"]},{"t":"水调歌头","f":"古风","c":["当局荐公起，清望益嵯峨。","旌旗者番南下，百骑照涛波。","帝念东南民瘼，一发牵之头动，亲问六州鹾。","宾客故人喜，愁绪恐公多。","公此去，令公喜，法如何。","金钱少府百万，挽入鲁阳戈。","公是登场鲍老，莫遣登场郭老，辩口尚悬河。","猿鹤北山下，一任檄文过。"]},{"t":"菩萨蛮 汉宫薰炉","f":"古风","c":["冶蓝活翠沈沈碧。","人间无此消魂色。","谁爇此炉香。","才人居未央。","摩挲还未忍。","心上温黁肯。","梦到古长安。","茂陵春雨寒。"]},{"t":"洞仙歌","f":"古风","c":["江东猿鹤，识人间花事。","十丈辛夷著花未。","忆春分尚早，梅信才完，花开了、狂蝶痴莺都睡。","此花开近处，不是朱楼，杰阁三层绝依倚。","高与玉山齐，露下遥天，定敕令、井桃回避。","又七载、低颜软尘红，向金马词场，讯他荣悴。"]},{"t":"洞仙歌","f":"古风","c":["香车枉顾，记临风一面，赠与琅玕簇如箭。","奈西风信早，北地寒多，埋没了、弹指芳华如电。","琴边空想像，陈迹难寻，谁料焦桐有人荐。","甘受灶丁怜，紫玉无言，惭愧煞、主人相见。","只未必、香魂夜归来，诉月下重逢，三生清怨。"]},{"t":"江城子","f":"古风","c":["不容红豆擅相思。","谢芳姿。","嫁多髭。","长爪仙人，化去已多时。","屏角迷藏帘畔景，留客罢，怪来迟。","小窗梅雨浥空卮。","掬芳蕤。","播幽篱。","疗可枯禅，难疗有情痴。","各有伤心茶话在，各焙出，鬓边丝。"]},{"t":"百字令","f":"古风","c":["江郎未老，尚追陪彩笔，多情俊侣。","禁苑山光天尺五，西北朱甍无数。","珂佩晨闲，文章秋横，祓禊西山雨。","尊前酹起，茶陵来和诗句。","猛记旧约湖山，长湾消夏，一舸寻幽去。","裙褶留仙无处问，瑟瑟秋荷南浦。","易稳鸥眠，难消虹气，且合词场住。","桥名相似，吟鞭醉失归路。"]},{"t":"青玉案","f":"古风","c":["钱塘词伯春怀动。","正献罢，长杨颂。","门外缁尘飞玉鞚。","长条冶叶，明窗画出，西子湖边梦。","三生清怨凭谁送。","悔向灵和殿前种。","头白沈郎官供奉。","要添几笔，濛濛飞絮，漠漠春芜重。"]},{"t":"南乡子","f":"古风","c":["相见便情长。","只有琅琊大道王。","三百年来文物感，苍茫。","身到亭亭九友旁。","梅雨好凄凉。","黦我丹青一扇香。","袖里珍擎怀里握，收藏。","合配君家赋九行。"]},{"t":"鹧鸪天頠躘塎煮《湖山旧雨轩图》","f":"古风","c":["双桨鸥波又一时。","大堤秋柳梦中垂。","关心我亦重来客，牢落黄金揖市儿。","长铗怨，破箫词。","两般合就鬓边丝。","兔毫留住伤心影，输与杭州老画师。"]},{"t":"贺新郎","f":"古风","c":["梦断秋无际。","滞幽人、一天残照，苍凉诗意。","何处帘栊何处院，金管玉箫浓醉。","有词客、如云而至。","侬有词场云水外，但凭栏、送尽征鸿字。","芳讯杳，九华佩。","春人只为春愁死。","几曾谙、篱边酒冷，笛边风起。","性懒情多兼骨傲，直得销魂如此。","与涧底、孤松一例。","谁料平原佳公子，也一般、识得秋滋味。","秋士怨，可知矣。"]},{"t":"凤凰台上忆吹箫","f":"古风","c":["白昼高眠，清琴慵理，闲官道力初成。","任东华人笑，大隐狂名。","侥幸词流云集，许陪坐、裙屐纵横。","看花去，哀歌弦罢，策蹇春城。","连旬。","朝回醉也，纵病后伤多，酒又沾唇。","对杜陵句里，万点愁人。","惹使鲁阳戈在，挽红日、重作青春。","江才尽，抽思骋妍，甘避诸宾。"]},{"t":"暗香","f":"古风","c":["一帆冷雨，有吴宫秋柳，留客小住。","笛里逢人，仙样风神画中语。","我是瑶华公子，从未识、露花风絮。","但深情、一往如潮，愁绝不能赋。","花雾。","障眉妩。","更明烛画桥，催打官鼓。","琐窗朱户。","一夜乌篷梦飞去。","何日量珠愿了，月底共、商量箫谱。","持半臂、亲也来，忍寒对汝。"]},{"t":"摸鱼儿","f":"古风","c":["笑银釭，一花宵绽，当筵即事如许。","我侬生小幽并住，悔不十年吴语。","凭听取。","算未要量珠，双角山头路。","生来蓬户。","只阿母憨怜，年华娇长，寒暖仗郎护。","筝和笛，十载教他原误。","人生百事辛苦。","五侯门第非侬宅，胜可五湖同去。","卿信否。","便千万商量，千万依分付。","花间好住。","倘燕燕归来，红帘双卷，认我写诗处。"]},{"t":"浪淘沙 映愿","f":"古风","c":["云外起朱楼。","缥缈清幽。","笛声叫破五湖秋。","整我图书三万轴，同上兰舟。","镜槛与香篝。","雅憺温柔。","替侬好好上帘钩。","湖水湖风凉不管，看汝梳头。"]},{"t":"洞仙歌 鄠缬鸾巢录别","f":"古风","c":["高楼灯火，已四更天气。","吴语喁喁也嫌碎。","者新居颇好，旧恨堪销，壶漏尽、侬待整帆行矣。","从今梳洗罢，收拾筝箫，匀出工夫学书字。","鸩鸟倘欺鸾，第一难防，须嘱咐、莺媒回避。","只此际、萧郎放心行，向水驿寻灯，山程倚辔。"]},{"t":"清平乐二首 其一","f":"古风","c":["人天辛苦。","恩怨谁为主。","几点枇杷花下雨。","葬送一春心绪。","梦中月射啼痕。","卷中灯灺诗痕。","一样嫦娥瞧见，问他谁冷谁温。"]},{"t":"清平乐二首 其二","f":"古风","c":["万千名士。","慰我伤谗意。","怜我平生无好计。","剑侠千年已矣。","西溪西去烟霞。","茅庵小有梅花。","绣佛长斋早早，忏渠燕子无家。"]},{"t":"法曲献仙音","f":"古风","c":["蓝布衫儿，墨紬裙子，未要艳妆明抹。","小小吴舠，山平水软，略昉鸱夷一舸。","待月上，清风细，无眠傍人坐。","倦无那。","细商量、隐沦休错。","年经小，料理五湖清妥。","绕屋种梅花，折梅花、供佛供我。","相鹤书成，又烦卿紬校灯火。","笑平生清恙，闲话一番医可。"]},{"t":"惜秋华 輠襔簪","f":"古风","c":["瑟瑟轻寒，正珠帘晓卷，秋心凄紧。","瘦蝶不来，飘零一天宫粉。","莫令真个敲残，留傍取、玉妆台近。","窥镜。","乍无人，一笑平添幽韵。","芳讯寄应准。","待穿来弱线，似玲珑情分。","移凤褥，欹宝枕，露乾香润。","秋人梦里相逢，记欲堕、又还黏鬓。","醒醒。","海棠边、慰他凉靓。"]},{"t":"减兰 輠畔孲","f":"古风","c":["栏干斜倚。","碧琉璃样轻花缀。","惨绿模糊。","瑟瑟凉痕欲晕初。","秋期此度。","秋星淡到无寻处。","宿露休搓。","恐是天孙别泪多。"]},{"t":"露华 輠孔手","f":"古风","c":["一痕轻软，受尽日沈沈，禅榻香满。","别样珑松，小擘露华犹泫。","斜挑玉柱停匀，握处兜罗难辨。","幽佳地，龙涎罢烧，银叶微暖。","空空妙手亲按。","是金粟如来，曾现好相曾现。","祗树天花，一种庄严谁见。","想因特地拈花，悟出真如不染。","维摩室，茶瓯经卷相伴。"]},{"t":"湘月","f":"古风","c":["勾留几日，把六朝俊语，取次听熟。","只说西洲清怨极，谁分者般秾福。","北海琴尊，东山弦管，小部泠泠曲。","昨宵梦里，画屏犹自银烛。","别后小有清吟，都无狂醉，冷煞闲官阁。","看取萧萧鸾尾影，翠袖天寒同宿。","铁笛吹残，瑶笺谱剩，料得怜幽独。","一枝赠我，安排早有金屋。"]},{"t":"浣溪沙","f":"七言古诗","c":["春倦如云不自持。","起书花叶畏人知。","斜阳倭妥绣帘垂。","凤约倥偬难解恨，莺期懊恼莫填词。","泪痕红上海棠枝。"]},{"t":"卜算子","f":"古风","c":["江上有高楼，可似湖楼迥。","楼外文波曲曲通，不驻惊鸿影。","蘋叶弄斜晖，兰蕊雕明镜。","剪尽秋花漠漠寒，人卧江南病。"]},{"t":"洞仙歌","f":"古风","c":["平生有恨，自酸酸楚楚。","十五年来梦中绪。","是纱衣天气，帘卷斜阳，相见了、有阵疏疏微雨。","临风针线净，爱惜馀明，抹丽鬘低倚当户。","庭果熟枇杷，亲蘸糖霜，消受彻、甘凉心腑。","索归去、依侬梦儿寻，怕不似儿时，那般庭宇。"]},{"t":"高阳台","f":"古风","c":["宫烛凄烟，庭梅妒月，扬州曾记元宵。","几度相逢，云萍依旧飘萧。","谢娘风格清寒甚，捧红丝、劝写无聊。","尽孤他，明月楼台，夜夜吹箫。","明知相约非相误，奈莺期不定，鸾镜终抛。","万一重逢，墨痕留认鲛绡。","青衫不渍清樽影，只模糊、红泪难销。","且禁他，今夜江风，明夜江潮。"]},{"t":"南浦","f":"古风","c":["羌笛落花天，办香鞯两两，愁人归去。","连夜梦魂飞，飞不到、天堑东头烟树。","空邮古戍，一灯败壁然诗句。","不信黄尘消不尽，摘粉搓脂情绪。","登车切莫回头，怕回头还见，高城尺五。","城里正端阳，香车过、多少青红儿女。","吟情太苦。","归来未算年华误。","一剑还君君莫问，换了江关词赋。"]},{"t":"齐天乐","f":"楚辞体","c":["东涂西抹寻常有，精灵可怜如许。","兜率天中，修罗海上，各是才人无数。","魂兮记取。","那半壁青山，我佣曾住。","花月濛濛，魂来魂往定相遇。","多君今世相仿，东南三百载，屈指吟侣。","花叶书成，云萍影合，沟水无情流去。","宾朋词赋。","好换了青灯，戒钟悲鼓。","翻遍华严，忏卿文字苦。"]},{"t":"绮寮怨","f":"古风","c":["一榻茶烟午寂，落花天易阴。","何人向、花外吹箫，惹清梦、飞出幽林。","江东俊游今倦，被怨曲、拨起情怎禁。","种闲愁，容易生苗，怕红豆，绿芜春又深。","人去休操断琴。","他生何许，此生有约难寻。","烟锁登临。","门巷昼沉沉。","天涯美人憔悴，云水外，定伤心。","伤心怕吟。","要消遣除听、千偈音。"]},{"t":"长相思二首 其一","f":"古风","c":["山溶溶。","水溶溶。","如梦如烟一万重。","谁期觉后逢。","恨应同。","誓应同。","同礼心经同听钟。","忏愁休更慵。"]},{"t":"长相思二首 其二","f":"古风","c":["画楼高。","画船摇。","君领琵琶侬领箫。","双鬓互见招。","茗能浇。","药能烧。","别有今生清课饶。","他生要福销。"]},{"t":"清平乐","f":"古风","c":["黄尘扑面。","寒了盟鸥愿。","问我名场谁教见。","冷抱寒陵一片。","别来容易经秋。","吴天清梦悠悠。","梦到一湾渔火，西山香雪归舟。"]},{"t":"卜算子","f":"古风","c":["曾在曲栏干，瞥见纱裙傍。","花影濛松细步回，月底帘钩上。","重到曲栏干，记起人模样。","万劫千生再见难，小影心头葬。"]},{"t":"采桑子","f":"古风","c":["沉思十五年中事，才也纵横。","泪也纵横。","双负萧心与剑心。","春来没个关心梦，自忏飘零。","不信飘零。","请看床头金字经。"]},{"t":"摸鱼儿","f":"古风","c":["又漫天、飞花飞絮，一番春事无据。","朝朝送客长亭岸，身似芦沟柳树。","归计阻。","但打叠吟魂，飞过黄河去。","输君容与。","者双髻吹笙，双声问字，双桨夜呼渡。","他生约，亦在五湖烟雨。","笛床歌板何处。","才人病后风情死，负了莫釐龙女。","还肯否。","重整顿清狂，也未年华暮。","幽怀漫诉。","要瀹茗烦他，舣舷待我，商略买山句。"]},{"t":"清平乐 頠胡鱼门《居山卷子》","f":"古风","c":["东南词赋。","屈指尊前数。","雨打风吹潮卷去。","依旧能狂只汝。","叩君画里禅关。","忆侬梦里烟鬟。","何日两枝玉笛，双双吹入春山。"]},{"t":"百字令","f":"古风","c":["龙华劫换，问何人料理，断金零粉。","五万春花如梦过，难遣些些春恨。","帐亸春宵，枕敧红玉，中有沧桑影。","定山堂畔，白头可照明镜。","记得肠断江南，花飞两岸，老去才还尽。","何不绛云楼下去，同礼空王钟磬。","青史闲看，红妆浅拜，回护吾宗肯。","漳江一传，心头蓦地来省。"]},{"t":"齐天乐","f":"古风","c":["相逢怕觅闲文字，替卿疗可春病。","难道才人，风风雨雨，埋却半生幽恨。","维摩消损。","有如愿天花，泥人出定。","一样中年，万千心绪待重整。","天涯此楼休问，一番枯寂后，须画金粉。","红烛填词，青绫拥被，春雨劝伊同听。","参禅也肯。","笑有限狂名，忏来易尽。","两幅青山，两家吟料井。"]},{"t":"好事近 欠月初十日即事","f":"古风","c":["兰桨昨同游，今日下楼无力。","嗔我凌晨来早，道不曾将息。","欢容惨黛霎时并，此景最难得。","别有神方持赠，为清明寒食。"]},{"t":"生查子 又即事一首","f":"五言律诗","c":["关了绿窗纱，松了湘裙衩。","言病复言愁，絮絮云屏下。","我已厌言愁，不理伤心话。","翻愿得娇嗔，故惹莺喉骂。"]},{"t":"鬲溪梅令 羽陵春晚画册","f":"古风","c":["矮桃花压石玲珑。","似巫峰。","花底鞋儿花外、月如弓。","入怀同不同。","郁金裙褶晚来松。","倦临风。","莫把胭脂先染、玉笙红。","制愁词思慵。"]},{"t":"丑奴儿令","f":"古风","c":["赤栏桥外垂杨柳，似我秋心。","一阵秋阴。","槭槭萧萧秋便深。","佛箭容我摊经坐，细剔龛灯。","多谢诗僧。","明夜挈舟又羽陵。"]},{"t":"人月圆","f":"古风","c":["绿珠不爱珊瑚树，情愿故侯家。","青门何有，几堆竹素，二顷梅花。","急得料理，成都贳酒，阳羡栽茶。","甘心费尽，三生慧业，万古才华。"]},{"t":"天仙子","f":"古风","c":["古来情语爱迷离。","恼煞王昌十五词。","楚天云雨到今疑。","铺玉版，捧红丝。","删尽刘郎本事诗。"]},{"t":"江城子","f":"古风","c":["假山修竹隐蒙茸。","忒玲珑。","似巫峰。","竹外楼台、薄暝一重重。","为数春星贪久立，苍藓上，印鞋弓。","留仙裙褶晚来松。","落花风。","去匆匆。","先把胭脂、染得玉笙红。","此夜酒边词笔健，银烛焰，吐如虹。"]},{"t":"阮郎归 代某校书送某书记","f":"古风","c":["碧桃花底醉春游。","横波先自秋。","明朝何况送兰舟。","情多易注眸。","纨扇小，纻衣修。","关山寸寸愁。","今番嫩约怕沈浮。","申江不许流。"]},{"t":"台城路","f":"古风","c":["山陬法物千年在，牧儿扣之声死。","谁信当年，楗棰一发，吼撤山河大地。","幽光灵气。","肯伺候梳妆，景阳宫里。","怕阅兴亡，何如移向草间置。","漫漫评尽古今，便汉家长乐，难寄身世。","也称人间，帝王宫殿，也称斜阳萧寺。","鲸鱼逝矣。","竟一卧东南，万牛难起。","笑煞铜仙，泪痕辞灞水。"]},{"t":"鹊桥仙 秦淮有访","f":"古风","c":["昨朝相见，浑如不见，鹦鹉催妆无力。","香消茶熟等多时，才镜槛、回廊一瞥。","今朝不见，胜如重见，庭院暮寒时节。","城闉灯火促归舟，露帘里、惨红裙褶。"]},{"t":"鬲溪梅令 猠潓","f":"古风","c":["林檎叶叶拂僧窗。","闪青釭。","墨菊如烟，淡与影儿双。","吠星何处尨。","梦中词笔小琤瑽。","寄吴艭。","欲剪芙蓉，生恐负兰茳。","不曾轻涉江。"]},{"t":"好事近","f":"古风","c":["三界最消魂，只有辩才天女。","半世从无一句，是平常言语。","倘然生小在侯家，天意转孤负。","作了槛花笼鹤，怎笑狂如许。"]},{"t":"台城路","f":"古风","c":["吴棉已把桃笙换，流光最惊羁旅。","蜡屐寻山，黄泥封酒，小有逢迎今雨。","怀沙辍赋。","梦不到南州，邓林夸父。","且逐寒潮，金阊一角饯秋去。","觉来谁与相遇。","有卷中姚合，楼上孙楚。","催我归舟，鸳鸯牒紧，莫恋闲鸥野鹭。","青溪粥鼓。","道来岁重寻，须携箫侣。","多谢词仙，低回吟冶句。"]},{"t":"应天长","f":"古风","c":["山僧许我移茶灶，不用当关仙鹤报。","松杉杪。","钟鱼杳。","天际真人相揖笑。","梦回曾似到。","记得卷中秋晓。","我吞长虹一啸，吴天落月小。"]},{"t":"点绛唇 攠记四月之游","f":"古风","c":["典却珠钗，高楼特启樱桃宴。","江风吹楝。","恰喜鲥鱼荐。","不许偎红，只许深杯劝。","窗三面。","推开一扇。","故使雏鬟见。"]},{"t":"好事近 攠记仲夏情事","f":"古风","c":["名俊出天然，字近曹娥碑格。","何以报他纨扇，馈一筐梅实。","平江暮雨太酸生，江上黯行色。","行过松陵古道，得断肠消息。"]},{"t":"虞美人","f":"古风","c":["高楼卜罢刍尼至。","读我龙鸾字。","门前青翰泊双双。","怕见芙蓉未敢涉秋江。","今年青鬓搔逾短。","那有忘忧馆。","文君倘制白头吟。","为报相如客里乏黄金。"]},{"t":"丑奴儿令 吠月坡半林订游","f":"古风","c":["游踪廿五年前到，江也依稀。","山也依稀。","少壮沈雄心事违。","词人问我重来意，吟也凄迷。","说也凄迷。","载得齐梁夕照归。"]},{"t":"定风波","f":"古风","c":["燕子矶头擪笛吹。","平明沈玉大王祠。","无数峨眉深院里。","晏起。","晓霜江上阿谁知。","山诡湖奔千万变。","当面。","身轻要唤鲤鱼骑。","蓦地江妃催我去。","飞渡。","樽前说与定何时。"]},{"t":"一痕沙","f":"古风","c":["东指羽陵山下。","小有亭楼如画。","松月夜窗虚。","待卿居。","闲却调筝素手。","只合替郎温酒。","高阁佛灯青。","替钞经。"]},{"t":"菩萨蛮 四月十九日薄暮即事","f":"古风","c":["文窗花雾凄然绿。","侍儿不肯传银烛。","楼外月昏黄。","口脂闻暗香。","新来情性皱。","未肯偎罗袖。","此度袷衣单。","蒙他讯晚寒。"]},{"t":"减兰","f":"古风","c":["鲚鱼桥下。","片片桃花春已谢。","不怨桥长。","行近伊家土亦香。","茶瓯香炷。","多谢小鬟传好语。","昨夜罗帏。","银烛花明蟢子飞。"]},{"t":"贺新凉侨寓吴霞沧浪亭，与王子梅诸君谈艺","f":"古风","c":["一棹沧浪水。","一行行、淡烟疏柳，平生秋思。","多谢江东风景好，依旧美人名士。","有老衲、高谈奇字。","使我吴天诗料阔，策蝌文、蜾扁三千事。","古香馤，在肝肺。","一箫我漫游吴市。","傍龛灯、来称教主，琉璃焰起。","病蝶凉蝉狂不得，还许虎丘秋禊。","看磨墨、人低双髻，绝胜山东驴子背，惨邮亭、麦饭黄沙里。","掷笔罢，傲吾子。"]},{"t":"好事近","f":"古风","c":["细语道家常，生小不矜珠翠。","他日郎家消受，愿青裙缟袂。","画梁燕子已无家，那有五侯第。","等到岁寒时候，折黄梅簪髻。"]},{"t":"小重山","f":"古风","c":["碧玉寒门产丽华。","误随红叶去，到天涯。","明珠一斛坐陪茶。","容我见，容我饭胡麻。","倦返七香车。","重寻吴苑柳，石湖花。","今年愁到莫愁家。","黄金少，典去玉丫叉。"]},{"t":"调笑令四首 其一","f":"古风","c":["花下。","花下。","金碧朝阳亭榭。","独游无味春时。","恨煞佳人起迟。","迟起。","迟起。","孤负江山清绮。"]},{"t":"调笑令四首 其二","f":"古风","c":["花月。","花月。","一片溶溶春阔。","佳人情味瞢腾。","翻爱罗帏拥灯。","灯歇。","灯歇。","我向花阴独立。"]},{"t":"调笑令四首 其三","f":"古风","c":["烹茗。","烹茗。","闲数东南流品。","美人俊辩风生。","皮里阳秋太明。","皮里。","皮里。","流品如侬第几。"]},{"t":"调笑令四首 其四","f":"古风","c":["年纪。","年纪。","不比十三十四。","乳名郑重曾探。","眉样蹉跎未谙。","眉样。","眉样。","难道峰青江上。"]},{"t":"定风波二首 其一","f":"古风","c":["拟聘云英药杵回。","思量一日万徘徊。","毕竟尘中容不得。","难说。","风前挥泪谢鸾媒。","自古畸人多性癖。","奇逸。","云中仙鹤怎笼来。","须信银屏金屋里。","一例。","琪花不称槛前栽。"]},{"t":"定风波二首 其二","f":"古风","c":["除是无愁与莫愁。","一身孤注掷温柔。","倘若有城还有国。","愁绝。","不能雄武不风流。","多谢尘言千百句。","难据。","羽陵词笔自今收。","晚岁披猖终未肯。","割忍。","他生缥缈此生休。"]},{"t":"卖花声","f":"古风","c":["我住秣陵西。","西鸟秋啼。","也无墨客对挥犀。","何处寻秋何处醉，小妹青溪。","寒菜两三畦。","花不成畦。","折归灯下伴凄迷。","忽忆青门人缟袂，淡墨曾题。"]},{"t":"卖花声 紫菊有近似墨菊者","f":"古风","c":["谁砑九秋光。","玉女玄霜。","胭脂队里铁为肠。","闻道豪家开夜宴，肯唤秋娘。","秋味黯然长。","不要秾香。","纸屏六幅绘湘江。","影忒似花花似影，小费评量。"]},{"t":"清平乐","f":"古风","c":["芙蓉老去。","没个销魂处。","今雨不来来旧雨。","心与亭台俱古。","青溪一曲盘桓。","粥鱼茶板荒寒。","多谢画师慰我，红妆打桨同还。"]},{"t":"南歌子 自题近词卷尾","f":"古风","c":["灵鹊飞秋夕，香车驾暮烟。","针儿七个尽情穿。","略费玲珑七孔藕心钱。","床上宜施宝，琴中替辨弦。","七襄报我定何年。","且喜南楼好梦七分圆。"]},{"t":"水龙吟","f":"古风","c":["虎头燕颔书生，相逢细把家门说。","乾隆丙午，鲸波不靖，凤山围急。","愤气成神，大招不反，东瀛荡坼。","便璇闺夜闭，影形相吊，髽子矮，秋灯碧。","宛宛玉钗一股，四十年、寒光不蚀。","微铿枕上，岂知中有，海天龙血。","甲子吟钗，壬申以殉，钗飞吟歇。","到而今，卷里钗声，如变徵，听还裂。"]},{"t":"后庭宴 用南唐人韵","f":"古风","c":["聘乏金钱，贮无金屋、嫁衣不用金泥簇。","青裙缟袂话三生，个侬道是楼东玉。","蛮笺宫体闲钞，他日娱卿幽独。","我歌得宝，不唱销魂曲。","何处是新巢，刺桐花䍡?。"]},{"t":"定风波 镨月十二日即事","f":"古风","c":["十里榴花一色裙。","三吴争赛楚灵均。","吴舞传芭如楚舞。","儿女。","中流箫管正纷纷。","别有高楼人一个。","独坐。","背灯偷学制回文。","许我幽寻凉月下。","闲话。","去年今日未逢君。"]},{"t":"水龙吟","f":"古风","c":["君家花月笙歌，葛裙那许陪宵燕。","啸如鲁柱，才如窦锦，遇如班扇。","蓬鬓慵妆，蛾眉怕妒，天寒谁管。","算平生已矣，春风一度，恩歇绝，何曾怨。","一夕仓皇家变，抱琵琶、倾城都散。","雍门琴碎，雀台香烬，西陵墓远。","块土争还，芳魂永守，秋燐如电。","忆史家、柱叔敖公，千载下，今重见。"]},{"t":"己亥杂诗 其一二八","f":"七言绝句","c":["黄河女直徙南东，我道神功胜禹功。","安用迂儒谈故道，犁然天地划民风。"]},{"t":"己亥杂诗 其一三○","f":"七言绝句","c":["陶潜酷似卧龙豪，万古浔阳松菊高。","莫信诗人竟平淡，二分梁甫一分骚。"]},{"t":"投宋于庭翔凤","f":"七言绝句","c":["游山五岳东道主，拥书百城南面王。","万人丛中一握手，使我衣袖三年香。"]}]};